import assert from "node:assert/strict"
import { spawnSync } from "node:child_process"
import * as fs from "node:fs/promises"
import * as os from "node:os"
import * as path from "node:path"
const root = path.resolve(process.argv[2] ?? "")
const taskId = process.argv[3]
const files = [{"path":"src/orchestrator/__tests__/cost-estimate.test.ts","source":"/**\n * Unit tests for src/orchestrator/cost-estimate.ts — the cost-history-based\n * task cost estimator (issue #16): per-shape aggregation and per-group\n * expected cost/iteration estimates for `orchestrate --dry-run`. Plain\n * assert-based, pure functions only (no fs, no network). Run via `npm test`.\n */\n\nimport assert from \"node:assert/strict\"\n\nimport type { CostHistoryRecord } from \"../cost-history.js\"\nimport type { SplitIssue, WorktreeSpec } from \"../split.js\"\nimport {\n\taggregateByShape,\n\tbuildEstimateSection,\n\tCI_CONFIG_HIGHER_BOUND_MULTIPLIER,\n\testimateGroups,\n\testimateIssue,\n\tisCiConfigChange,\n\tisVerificationHeavy,\n\tlowConfidenceReason,\n\tMIN_SHAPE_SAMPLES,\n\tTEST_SHAPE_VERIFICATION_MULTIPLIER,\n\tVERIFICATION_MULTIPLIER_FULL_SAMPLES,\n\tverificationMultiplier,\n} from \"../cost-estimate.js\"\n\n// ─── Helpers ─────────────────────────────────────────────────────────────────\n\n/** Float-tolerant equality (medians of e.g. [0.2, 0.4] land on 0.30000000000000004). */\nfunction assertClose(actual: number, expected: number, msg = \"\"): void {\n\tassert.ok(Math.abs(actual - expected) <= 1e-9, `${msg} expected ${actual} ~= ${expected}`)\n}\n\nfunction record(overrides: Partial<CostHistoryRecord> = {}): CostHistoryRecord {\n\treturn {\n\t\trecordedAt: \"2026-08-05T00:00:00.000Z\",\n\t\trepo: \"/tmp/repo\",\n\t\tgroupName: \"w1\",\n\t\tissues: [27],\n\t\tshapes: [\"split\"],\n\t\tstatus: \"done\",\n\t\tcostUsd: 0.2,\n\t\tinputTokens: 2000,\n\t\toutputTokens: 200,\n\t\tcachedTokens: 0,\n\t\titerations: 40,\n\t\tcontinuationCount: 0,\n\t\treworkCount: 0,\n\t\t...overrides,\n\t}\n}\n\nfunction issue(number: number, title: string, body?: string): SplitIssue {\n\treturn { number, title, body }\n}\n\nfunction spec(name: string, issues: number[]): WorktreeSpec {\n\treturn { name, issues, taskFile: `${name}-issue${issues.join(\"-\")}.md` }\n}\n\n// ─── Tests ───────────────────────────────────────────────────────────────────\n\nasync function testAggregateByShapeGroupsAndSkipsShapeless(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"g1\", issues: [27], shapes: [\"split\"], costUsd: 0.2, iterations: 40, continuationCount: 0, reworkCount: 1 }),\n\t\trecord({ groupName: \"g2\", issues: [28], shapes: [\"split\"], costUsd: 0.4, iterations: 60, continuationCount: 1, reworkCount: 0 }),\n\t\trecord({ groupName: \"g3\", issues: [30], shapes: [\"docs\"], costUsd: 0.1, iterations: 20 }),\n\t\t// Written before issue #16's shapes field existed — must not contribute.\n\t\trecord({ groupName: \"g4\", issues: [31], shapes: undefined, costUsd: 5.0 }),\n\t]\n\tconst stats = aggregateByShape(records)\n\tassert.equal(stats.length, 2, \"shapeless records must not create a shape bucket\")\n\tconst split = stats.find((s) => s.shape === \"split\")\n\tassert.ok(split, \"split shape present\")\n\tassert.equal(split?.samples, 2)\n\tassert.equal(split?.costMinUsd, 0.2)\n\tassertClose(split?.costMedianUsd ?? 0, 0.3, \"median of [0.2, 0.4]\")\n\tassert.equal(split?.costMaxUsd, 0.4)\n\tassertClose(split?.costPerIssueMedianUsd ?? 0, 0.3, \"single-issue records: per-issue == group cost\")\n\tassert.equal(split?.iterationsMedian, 50)\n\tassert.equal(split?.continuationRate, 0.5, \"mean continuation cycles per group\")\n\tassert.equal(split?.reworkRate, 0.5)\n\tconst docs = stats.find((s) => s.shape === \"docs\")\n\tassert.equal(docs?.samples, 1)\n\tassert.equal(docs?.costMedianUsd, 0.1)\n\t// Sorted by samples descending: split (2) before docs (1).\n\tassert.equal(stats[0]?.shape, \"split\")\n}\n\nasync function testAggregateByShapeMixedGroupCountsOncePerShape(): Promise<void> {\n\t// A group covering a split issue AND a docs issue is evidence about both\n\t// shapes — but must not be double-counted for either.\n\tconst records = [record({ groupName: \"g1\", issues: [29, 36], shapes: [\"split\", \"docs\"], costUsd: 0.6, iterations: 90 })]\n\tconst stats = aggregateByShape(records)\n\tassert.equal(stats.length, 2)\n\tfor (const s of stats) {\n\t\tassert.equal(s.samples, 1, \"a mixed group contributes once per shape\")\n\t\tassert.equal(s.costPerIssueMedianUsd, 0.3, \"per-issue cost normalizes across the group's 2 issues\")\n\t}\n}\n\nasync function testEstimateIssueDirectMatchBeatsShapeMatch(): Promise<void> {\n\t// Issue 7 was worked on before (a direct record); generic-shape records\n\t// also exist. The direct record must win even though it's a single sample.\n\tconst records = [\n\t\trecord({ groupName: \"past\", issues: [7], shapes: [\"generic\"], costUsd: 0.5, iterations: 70 }),\n\t\trecord({ groupName: \"a\", issues: [1], shapes: [\"generic\"], costUsd: 0.1, iterations: 30 }),\n\t\trecord({ groupName: \"b\", issues: [2], shapes: [\"generic\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"c\", issues: [3], shapes: [\"generic\"], costUsd: 0.3, iterations: 50 }),\n\t]\n\tconst direct = estimateIssue(records, 7, \"generic\")\n\tassert.equal(direct.match, \"direct\")\n\tassert.equal(direct.samples, 1)\n\tassert.equal(direct.costPerIssueUsd, 0.5)\n\tassert.deepEqual(direct.costPerIssueRangeUsd, [0.5, 0.5])\n\n\tconst byShape = estimateIssue(records, 8, \"generic\")\n\tassert.equal(byShape.match, \"shape\")\n\tassert.equal(byShape.samples, 4)\n\tassert.equal(byShape.costPerIssueUsd, 0.25, \"median of the 4 generic records' per-issue costs\")\n\tassert.deepEqual(byShape.costPerIssueRangeUsd, [0.1, 0.5])\n}\n\nasync function testEstimateIssueShapeNeedsMinSamples(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [1], shapes: [\"split\"], costUsd: 0.1 }),\n\t\trecord({ groupName: \"b\", issues: [2], shapes: [\"split\"], costUsd: 0.2 }),\n\t]\n\tconst estimate = estimateIssue(records, 99, \"split\")\n\tassert.equal(estimate.match, \"shape\", \"a partial sample set still reports the shape match...\")\n\tassert.equal(estimate.samples, 2)\n\tassert.equal(estimate.costPerIssueUsd, undefined, \"...but offers NO numbers below MIN_SHAPE_SAMPLES\")\n\tassert.equal(MIN_SHAPE_SAMPLES, 3)\n}\n\nasync function testEstimateIssueNoMatch(): Promise<void> {\n\tconst estimate = estimateIssue([], 42, \"docs\")\n\tassert.equal(estimate.match, \"none\")\n\tassert.equal(estimate.samples, 0)\n\tassert.equal(estimate.costPerIssueUsd, undefined)\n}\n\n// ─── Issue #124: verification-intensity multiplier ───────────────────────────\n\nasync function testIsVerificationHeavy(): Promise<void> {\n\tassert.equal(isVerificationHeavy(\"test\", undefined), true, \"test shape is verification-heavy by definition\")\n\tassert.equal(isVerificationHeavy(\"split\", undefined), false)\n\tassert.equal(\n\t\tisVerificationHeavy(\"coverage\", issue(9, \"COV-1: add GitHub Actions CI config\")),\n\t\ttrue,\n\t\t\"CI/GitHub Actions mention in the title marks the issue verification-heavy\",\n\t)\n\tassert.equal(\n\t\tisVerificationHeavy(\"split\", issue(10, \"Split utils\", \"Adds a workflow that runs tests on a runner\")),\n\t\ttrue,\n\t\t\"workflow/runner mention in the body marks the issue verification-heavy\",\n\t)\n\tassert.equal(isVerificationHeavy(\"docs\", issue(11, \"Document the API\")), false)\n}\n\nasync function testVerificationMultiplierTapersWithSamples(): Promise<void> {\n\t// Direct match: trusted as-is, no multiplier even for a test shape.\n\tassert.equal(verificationMultiplier(\"test\", undefined, \"direct\", 1), 1, \"direct match never scaled\")\n\t// Not verification-heavy: no multiplier regardless of samples.\n\tassert.equal(verificationMultiplier(\"split\", undefined, \"shape\", 3), 1)\n\t// Below MIN_SHAPE_SAMPLES the multiplier is CLAMPED at the full value —\n\t// regression (rework cycle 1): the old taper formula extrapolated below\n\t// MIN_SHAPE_SAMPLES, returning 3.5 at 1 sample and 3.0 at 2, above the\n\t// documented 2.5 cap. Thin-but-nonzero samples get the full scale, never\n\t// more.\n\tassertClose(\n\t\tverificationMultiplier(\"test\", undefined, \"shape\", 1),\n\t\tTEST_SHAPE_VERIFICATION_MULTIPLIER,\n\t\t\"1 sample clamps at the full multiplier, never above it\",\n\t)\n\tassertClose(\n\t\tverificationMultiplier(\"test\", undefined, \"shape\", 2),\n\t\tTEST_SHAPE_VERIFICATION_MULTIPLIER,\n\t\t\"2 samples clamp at the full multiplier, never above it\",\n\t)\n\t// Test shape at MIN_SHAPE_SAMPLES: full multiplier.\n\tassertClose(\n\t\tverificationMultiplier(\"test\", undefined, \"shape\", MIN_SHAPE_SAMPLES),\n\t\tTEST_SHAPE_VERIFICATION_MULTIPLIER,\n\t\t\"full multiplier at MIN_SHAPE_SAMPLES\",\n\t)\n\t// Fully sampled: trusted as-is.\n\tassert.equal(\n\t\tverificationMultiplier(\"test\", undefined, \"shape\", VERIFICATION_MULTIPLIER_FULL_SAMPLES),\n\t\t1,\n\t\t\"no multiplier once real samples accumulate\",\n\t)\n\t// Between the two: linear taper.\n\tconst mid = verificationMultiplier(\"test\", undefined, \"shape\", 4)\n\tassert.ok(mid > 1 && mid < TEST_SHAPE_VERIFICATION_MULTIPLIER, `mid-samples multiplier tapers (got ${mid})`)\n\t// No usable numeric estimate (0 samples): 1 (nothing to scale).\n\tassert.equal(verificationMultiplier(\"test\", undefined, \"shape\", 0), 1)\n}\n\nasync function testEstimateIssueTestShapeScalesCostNotIterations(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"test\"], costUsd: 0.1, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"test\"], costUsd: 0.2, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"test\"], costUsd: 0.3, iterations: 60 }),\n\t]\n\tconst estimate = estimateIssue(records, 99, \"test\", issue(99, \"Add tests for the parser\"))\n\tassert.equal(estimate.match, \"shape\")\n\tassert.equal(estimate.samples, 3)\n\t// Median per-issue cost $0.2 * 2.5 = $0.5; iterations NOT scaled.\n\tassertClose(estimate.costPerIssueUsd ?? 0, 0.2 * TEST_SHAPE_VERIFICATION_MULTIPLIER, \"test-shape cost scaled up\")\n\tassert.equal(estimate.iterationsPerIssue, 50, \"iterations not scaled by the verification multiplier\")\n\tassert.deepEqual(estimate.costPerIssueRangeUsd, [0.1 * 2.5, 0.3 * 2.5], \"range scaled too\")\n\tassertClose(estimate.verificationMultiplier ?? 0, TEST_SHAPE_VERIFICATION_MULTIPLIER, \"multiplier recorded on the estimate\")\n}\n\nasync function testEstimateIssueCiMentionScalesEvenWithOtherShape(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"coverage\"], costUsd: 0.1, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"coverage\"], costUsd: 0.2, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"coverage\"], costUsd: 0.3, iterations: 60 }),\n\t]\n\t// \"COV-1\"-style: a coverage-shaped issue whose remediation adds CI config.\n\tconst estimate = estimateIssue(records, 99, \"coverage\", issue(99, \"COV-1: add coverage with GitHub Actions CI\"))\n\tassert.equal(estimate.match, \"shape\")\n\tassertClose(estimate.costPerIssueUsd ?? 0, 0.2 * TEST_SHAPE_VERIFICATION_MULTIPLIER, \"CI-bearing issue cost scaled up\")\n}\n\nasync function testEstimateIssueWellSampledTestShapeNotScaled(): Promise<void> {\n\tconst records = [1, 2, 3, 4, 5, 6, 7].map((n) =>\n\t\trecord({ groupName: `g${n}`, issues: [n], shapes: [\"test\"], costUsd: 0.2, iterations: 50 }),\n\t)\n\tconst estimate = estimateIssue(records, 99, \"test\", issue(99, \"Add tests\"))\n\tassert.equal(estimate.samples, 7)\n\tassertClose(estimate.costPerIssueUsd ?? 0, 0.2, \"well-sampled test shape is trusted as-is\")\n\tassert.equal(estimate.verificationMultiplier, 1)\n}\n\nasync function testEstimateGroupsShowsVerificationMultiplier(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"test\"], costUsd: 0.1, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"test\"], costUsd: 0.2, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"test\"], costUsd: 0.3, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Add tests for the API\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29])], issues)\n\tassert.equal(groups[0]?.verificationMultiplier, TEST_SHAPE_VERIFICATION_MULTIPLIER)\n\tassertClose(groups[0]?.expectedCostUsd ?? 0, 0.2 * TEST_SHAPE_VERIFICATION_MULTIPLIER, \"group cost includes the scaled issue\")\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.match(lines[0] ?? \"\", /2\\.50x verification multiplier/, \"dry-run line names the multiplier\")\n}\n\nasync function testEstimateGroupsDoesNotSurfaceUnappliedMultiplier(): Promise<void> {\n\t// A mixed group: 1 test-shaped record (thin — below MIN_SHAPE_SAMPLES, so\n\t// the test issue contributes NO cost) + 3 split-shaped records (usable,\n\t// scaled 1.0). Regression (rework cycle 1): the old code surfaced the max\n\t// per-issue multiplier (3.5 at 1 sample) next to a cost it never scaled —\n\t// the \"3.50x\" on the dry-run line was a false claim exceeding the cap.\n\tconst records = [\n\t\trecord({ groupName: \"t1\", issues: [100], shapes: [\"test\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"a\", issues: [101], shapes: [\"split\"], costUsd: 0.1, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [102], shapes: [\"split\"], costUsd: 0.2, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [103], shapes: [\"split\"], costUsd: 0.3, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Add tests for the API\"), issue(5, \"Split the big file into modules\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29, 5])], issues)\n\tconst g = groups[0]\n\tassert.equal(g?.unmatched, 1, \"the thin test issue contributes no usable cost\")\n\tassertClose(g?.expectedCostUsd ?? 0, 0.2, \"only the split issue contributes ($0.2 median, unscaled)\")\n\tassert.equal(g?.verificationMultiplier, undefined, \"no multiplier surfaces — nothing usable was scaled\")\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.doesNotMatch(lines[0] ?? \"\", /verification multiplier/, \"dry-run line must not claim a multiplier that never scaled the cost\")\n}\n\nasync function testEstimateGroupsSumsPerIssueIntoGroup(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"split\"], costUsd: 0.4, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Split the big file into modules\"), issue(36, \"Decompose views.py too\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29, 36])], issues)\n\tassert.equal(groups.length, 1)\n\tconst g = groups[0]\n\tassert.equal(g.expectedCostUsd, 0.6, \"two split issues at $0.30 per-issue median\")\n\tassert.deepEqual(g.costRangeUsd, [0.4, 0.8], \"sum of per-issue min/max across the two issues\")\n\tassert.equal(g.expectedIterations, 100, \"two issues at 50 iterations median\")\n\tassert.deepEqual(g.shapes, [\"split\"])\n\tassert.equal(g.unmatched, 0)\n}\n\nasync function testEstimateGroupsPartialMatchReportsUnmatched(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"split\"], costUsd: 0.4, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Split the big file\"), issue(12, \"Add docs for the API\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29, 12])], issues)\n\tassert.equal(groups[0]?.unmatched, 1, \"the docs issue has no matching history\")\n\tassert.equal(groups[0]?.expectedCostUsd, 0.3, \"only the matched split issue contributes\")\n}\n\nasync function testBuildEstimateSectionEmptyHistory(): Promise<void> {\n\tconst issues = [issue(1, \"Fix the thing\")]\n\tconst groups = estimateGroups([], [spec(\"w1\", [1])], issues)\n\tconst lines = buildEstimateSection(groups, 0)\n\tassert.equal(lines.length, 1)\n\tassert.match(lines[0] ?? \"\", /no cost history recorded yet/)\n}\n\nasync function testBuildEstimateSectionSufficientData(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"split\"], costUsd: 0.4, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Split the big file into modules\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29])], issues)\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.equal(lines.length, 2)\n\tassert.match(lines[0] ?? \"\", /w1 \\(issues 29 — split\\): expected ~\\$0\\.2000–\\$0\\.4000 · ~40–60 iterations · 3 sample\\(s\\)/)\n\tassert.match(lines[1] ?? \"\", /continuation\\/rework: 0\\.0 \\/ 0\\.0 cycles per group avg/)\n}\n\nasync function testBuildEstimateSectionInsufficientData(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t]\n\tconst issues = [issue(29, \"Split the big file into modules\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29])], issues)\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.match(lines[0] ?? \"\", /insufficient data \\(2 sample\\(s\\), need 3\\) — no estimate yet/)\n}\n\nasync function testBuildEstimateSectionNoHistoryForShape(): Promise<void> {\n\t// History exists overall, but nothing matches this issue's shape.\n\tconst records = [record({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 })]\n\tconst issues = [issue(12, \"Add docs for the API\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [12])], issues)\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.match(lines[0] ?? \"\", /no history for this shape yet/)\n}\n\n// ─── Issue #125: CI/config-change higher bound ───────────────────────────────\n\nasync function testIsCiConfigChangeMatchesTitleAndBody(): Promise<void> {\n\tassert.ok(isCiConfigChange(issue(1, \"Add CI workflow for tests\")), \"title 'CI workflow'\")\n\tassert.ok(isCiConfigChange(issue(2, \"Fix the GitHub Actions runner config\")), \"title 'Actions runner'\")\n\tassert.ok(\n\t\tisCiConfigChange(issue(3, \"Bump deps\", \"The workflow file at .github/workflows/ci.yml needs updating\")),\n\t\t\"body 'workflow'\",\n\t)\n\tassert.ok(!isCiConfigChange(issue(4, \"Refactor user auth\")), \"plain refactor\")\n\tassert.ok(!isCiConfigChange(issue(5, \"Handle transactions safely\")), \"'transactions' contains 'actions' but is not CI\")\n}\n\nasync function testCiConfigIssueGetsFlaggedHigherBound(): Promise<void> {\n\t// 3 split records: the CI issue's shape estimate is a normal per-issue\n\t// median; its flagged higher bound is that median * multiplier, and the\n\t// group total's higher bound replaces the CI issue's contribution. The\n\t// title keeps the \"split\" shape (\"Split ... actions ...\") so it matches\n\t// the split records and trips CI_CONFIG_RE (\\bactions\\b) WITHOUT also\n\t// tripping CI_MENTION_RE's verification-heavy signal (issue #124), which\n\t// requires \"github actions\"/\"ci\"/\"workflow\"/\"runner\" as a unit — this\n\t// isolates the #125 flagged-bound behavior from the #124 cost multiplier\n\t// so the two independently-stacking features can each be tested alone.\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"split\"], costUsd: 0.4, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Split the release actions into modules\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29])], issues)\n\tconst g = groups[0]\n\tconst perIssue = g?.perIssue[0]\n\tassert.equal(perIssue?.ciConfig, true, \"CI/config issue is flagged\")\n\tassert.equal(perIssue?.costPerIssueUsd, 0.3, \"plain shape estimate is still the split median\")\n\tassertClose(\n\t\tperIssue?.higherBoundUsd ?? 0,\n\t\t0.3 * CI_CONFIG_HIGHER_BOUND_MULTIPLIER,\n\t\t\"per-issue higher bound = median * multiplier\",\n\t)\n\tassertClose(g?.higherBoundUsd ?? 0, 0.3 * CI_CONFIG_HIGHER_BOUND_MULTIPLIER, \"group higher bound rolls the flagged issue in\")\n\tassert.equal(g?.expectedCostUsd, 0.3, \"expectedCostUsd stays the plain median\")\n}\n\nasync function testCiConfigHigherBoundMixesWithNonCiIssues(): Promise<void> {\n\t// One CI issue + one plain issue: the group higher bound = CI bound +\n\t// plain median; the plain expected total is the sum of both medians.\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"split\"], costUsd: 0.4, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Split the release actions into modules\"), issue(36, \"Split the big file into modules\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29, 36])], issues)\n\tconst g = groups[0]\n\tassertClose(g?.expectedCostUsd ?? 0, 0.6, \"both medians sum into the plain total\")\n\tassertClose(\n\t\tg?.higherBoundUsd ?? 0,\n\t\t0.3 * CI_CONFIG_HIGHER_BOUND_MULTIPLIER + 0.3,\n\t\t\"CI issue contributes its higher bound, the plain issue its median\",\n\t)\n}\n\nasync function testBuildEstimateSectionShowsCiHigherBound(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"split\"], costUsd: 0.4, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Split the release actions into modules\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29])], issues)\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.ok(\n\t\tlines.some((l) => l.includes(\"CI/config work: higher bound ~$0.9000\")),\n\t\t`higher bound rendered on the estimate line: ${lines.join(\" | \")}`,\n\t)\n}\n\n// ─── Issue #126: LOW-CONFIDENCE warnings ─────────────────────────────────────\n\nasync function testLowConfidenceFlaggedWhenIssuesUnmatched(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"split\"], costUsd: 0.4, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Split the big file\"), issue(12, \"Add docs for the API\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29, 12])], issues)\n\tconst g = groups[0]\n\tassert.equal(g?.unmatched, 1)\n\tassert.equal(g?.lowConfidence, true, \"an unmatched issue's excluded cost makes the total low-confidence\")\n\tassert.match(lowConfidenceReason(g), /1 issue\\(s\\) unmatched/)\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.ok(\n\t\tlines.some((l) => l.includes(\"⚠ LOW-CONFIDENCE\") && l.includes(\"unmatched\")),\n\t\t`unmatched low-confidence rendered: ${lines.join(\" | \")}`,\n\t)\n}\n\nasync function testLowConfidenceFlaggedOnNoHistoryForShape(): Promise<void> {\n\tconst records = [record({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 })]\n\tconst issues = [issue(12, \"Add docs for the API\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [12])], issues)\n\tconst g = groups[0]\n\tassert.equal(g?.lowConfidence, true, \"no usable history -> low-confidence\")\n\tassert.match(lowConfidenceReason(g), /no history for this shape yet/)\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.ok(\n\t\tlines.some((l) => l.includes(\"⚠ LOW-CONFIDENCE\") && l.includes(\"no history\")),\n\t\t`no-history low-confidence rendered: ${lines.join(\" | \")}`,\n\t)\n}\n\nasync function testLowConfidenceFlaggedOnInsufficientSamples(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t]\n\tconst issues = [issue(29, \"Split the big file into modules\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29])], issues)\n\tconst g = groups[0]\n\tassert.equal(g?.lowConfidence, true, \"2 samples < MIN_SHAPE_SAMPLES -> low-confidence\")\n\tassert.match(lowConfidenceReason(g), /insufficient history/)\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.ok(\n\t\tlines.some((l) => l.includes(\"⚠ LOW-CONFIDENCE\")),\n\t\t`insufficient-samples low-confidence rendered: ${lines.join(\" | \")}`,\n\t)\n}\n\nasync function testLowConfidenceNotFlaggedWithEnoughSamples(): Promise<void> {\n\tconst records = [\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"split\"], costUsd: 0.4, iterations: 60 }),\n\t]\n\tconst issues = [issue(29, \"Split the big file into modules\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [29])], issues)\n\tconst g = groups[0]\n\tassert.equal(g?.lowConfidence, false, \"3 samples, all matched -> solid estimate\")\n\tconst lines = buildEstimateSection(groups, records.length)\n\tassert.ok(\n\t\t!lines.some((l) => l.includes(\"LOW-CONFIDENCE\")),\n\t\t`no LOW-CONFIDENCE marker on a solid estimate: ${lines.join(\" | \")}`,\n\t)\n}\n\nasync function testLowConfidenceFlaggedOnUnderSampledDirectMatch(): Promise<void> {\n\t// A direct issue-number match with a SINGLE record is offered (it IS\n\t// meaningful) but is an anecdote — low-confidence (issue #126).\n\tconst records = [\n\t\trecord({ groupName: \"past\", issues: [7], shapes: [\"split\"], costUsd: 0.5, iterations: 70 }),\n\t\trecord({ groupName: \"a\", issues: [100], shapes: [\"split\"], costUsd: 0.2, iterations: 40 }),\n\t\trecord({ groupName: \"b\", issues: [101], shapes: [\"split\"], costUsd: 0.3, iterations: 50 }),\n\t\trecord({ groupName: \"c\", issues: [102], shapes: [\"split\"], costUsd: 0.4, iterations: 60 }),\n\t]\n\tconst issues = [issue(7, \"Re-open: add a CI workflow (was split before)\")]\n\tconst groups = estimateGroups(records, [spec(\"w1\", [7])], issues)\n\tconst g = groups[0]\n\tassert.equal(g?.perIssue[0]?.match, \"direct\")\n\tassert.equal(g?.perIssue[0]?.samples, 1)\n\tassert.equal(g?.lowConfidence, true, \"single-record direct match is low-confidence\")\n\tassert.match(lowConfidenceReason(g), /single-run anecdote/)\n}\n\n// ─── Runner ──────────────────────────────────────────────────────────────────\n\nconst tests: Array<[string, () => Promise<void>]> = [\n\t[\"aggregateByShape groups by shape, skips shapeless records, computes medians/rates\", testAggregateByShapeGroupsAndSkipsShapeless],\n\t[\"aggregateByShape counts a mixed-shape group once per shape, normalizes per issue\", testAggregateByShapeMixedGroupCountsOncePerShape],\n\t[\"estimateIssue: exact issue-number history beats shape matching\", testEstimateIssueDirectMatchBeatsShapeMatch],\n\t[\"estimateIssue: shape matching needs MIN_SHAPE_SAMPLES before offering numbers\", testEstimateIssueShapeNeedsMinSamples],\n\t[\"estimateIssue: no matching history -> match none\", testEstimateIssueNoMatch],\n\t[\"isVerificationHeavy: test shape and CI mention detection (issue #124)\", testIsVerificationHeavy],\n\t[\"verificationMultiplier: tapers from full multiplier to 1 as samples accumulate (issue #124)\", testVerificationMultiplierTapersWithSamples],\n\t[\"estimateIssue: test shape scales COST, not iterations (issue #124)\", testEstimateIssueTestShapeScalesCostNotIterations],\n\t[\"estimateIssue: CI/GitHub Actions mention scales cost even with another shape (issue #124)\", testEstimateIssueCiMentionScalesEvenWithOtherShape],\n\t[\"estimateIssue: well-sampled test shape is trusted as-is (issue #124)\", testEstimateIssueWellSampledTestShapeNotScaled],\n\t[\"estimateGroups: verification multiplier surfaces on the group + dry-run line (issue #124)\", testEstimateGroupsShowsVerificationMultiplier],\n\t[\"estimateGroups: an unapplied multiplier (thin issue contributes no cost) never surfaces (rework cycle 1)\", testEstimateGroupsDoesNotSurfaceUnappliedMultiplier],\n\t[\"estimateGroups sums per-issue medians into a group range\", testEstimateGroupsSumsPerIssueIntoGroup],\n\t[\"estimateGroups reports unmatched issues as partial\", testEstimateGroupsPartialMatchReportsUnmatched],\n\t[\"buildEstimateSection: empty history -> single no-history note\", testBuildEstimateSectionEmptyHistory],\n\t[\"buildEstimateSection: sufficient data -> expected range + rates\", testBuildEstimateSectionSufficientData],\n\t[\"buildEstimateSection: sparse data -> explicit insufficient-data note\", testBuildEstimateSectionInsufficientData],\n\t[\"buildEstimateSection: unrelated shapes -> no-history-for-this-shape note\", testBuildEstimateSectionNoHistoryForShape],\n\t[\"isCiConfigChange matches CI/actions/workflow/runner in title+body, rejects lookalikes\", testIsCiConfigChangeMatchesTitleAndBody],\n\t[\"CI/config issue gets a flagged higher bound (per-issue and group, #125)\", testCiConfigIssueGetsFlaggedHigherBound],\n\t[\"CI/config higher bound mixes with plain issues in the group total (#125)\", testCiConfigHigherBoundMixesWithNonCiIssues],\n\t[\"buildEstimateSection renders the CI higher bound on the estimate line (#125)\", testBuildEstimateSectionShowsCiHigherBound],\n\t[\"LOW-CONFIDENCE flagged + rendered when issues are unmatched (#126)\", testLowConfidenceFlaggedWhenIssuesUnmatched],\n\t[\"LOW-CONFIDENCE flagged + rendered when no history for the shape (#126)\", testLowConfidenceFlaggedOnNoHistoryForShape],\n\t[\"LOW-CONFIDENCE flagged + rendered when samples < MIN_SHAPE_SAMPLES (#126)\", testLowConfidenceFlaggedOnInsufficientSamples],\n\t[\"no LOW-CONFIDENCE marker when the estimate is solid (#126)\", testLowConfidenceNotFlaggedWithEnoughSamples],\n\t[\"LOW-CONFIDENCE flagged on an under-sampled direct match (#126)\", testLowConfidenceFlaggedOnUnderSampledDirectMatch],\n]\n\nasync function main(): Promise<void> {\n\tlet failed = 0\n\tfor (const [name, fn] of tests) {\n\t\ttry {\n\t\t\tawait fn()\n\t\t\tconsole.log(`  ok   ${name}`)\n\t\t} catch (err) {\n\t\t\tfailed++\n\t\t\tconsole.error(`  FAIL ${name}`)\n\t\t\tconsole.error(err instanceof Error ? (err.stack ?? err.message) : String(err))\n\t\t}\n\t}\n\tif (failed > 0) {\n\t\tconsole.error(`\\n${failed} test(s) failed`)\n\t\tprocess.exit(1)\n\t}\n\tconsole.log(`\\nAll ${tests.length} cost-estimate tests passed`)\n}\n\nmain().catch((err) => {\n\tconsole.error(\"Test runner crashed:\", err)\n\tprocess.exit(1)\n})"},{"path":"src/orchestrator/__tests__/status-cli.test.ts","source":"/**\n * Unit tests for `headlesscode orchestrate status` (src/orchestrator/cli.ts's\n * statusMain + src/orchestrator/status.ts) — the read-side status/wait\n * command external callers use instead of hand-rolled poll loops over\n * .orchestrator-state.json. Plain assert-based (no framework, no network)\n * matching the repo test style. Run via `npm test`.\n */\n\nimport assert from \"node:assert/strict\"\nimport * as fs from \"node:fs/promises\"\nimport * as os from \"node:os\"\nimport * as path from \"node:path\"\n\nimport { parseStatusArgs, statusMain } from \"../cli.js\"\nimport { reconcileGroups, waitForTerminalState } from \"../status.js\"\nimport {\n\tdefaultState,\n\tloadStateSync,\n\tsaveStateSync,\n\tupdateGroup,\n\ttype OrchestratorGroup,\n\ttype OrchestratorState,\n} from \"../state.js\"\n\nasync function tmpRepo(): Promise<string> {\n\treturn fs.mkdtemp(path.join(os.tmpdir(), \"headlesscode-status-\"))\n}\n\nfunction baseGroup(overrides: Partial<OrchestratorGroup> = {}): OrchestratorGroup {\n\treturn {\n\t\tname: \"w1\",\n\t\tworktree: \".worktrees/w1\",\n\t\tstatus: \"running\",\n\t\tspawned: new Date().toISOString(),\n\t\t...overrides,\n\t}\n}\n\n/** A 3-group fixture: one done, one failed, one running, plus round totals. */\nfunction mixedState(): OrchestratorState {\n\tlet state = defaultState(\"r1\")\n\tstate = updateGroup(state, \"w-done\", baseGroup({ name: \"w-done\", status: \"done\", last_activity: \"merged to master\" }))\n\tstate = updateGroup(state, \"w-fail\", baseGroup({ name: \"w-fail\", status: \"failed\", exit_code: 7 }))\n\tstate = updateGroup(state, \"w-run\", baseGroup({ name: \"w-run\", status: \"running\" }))\n\tstate.totalUsage = { costUsd: 0.042, inputTokens: 1000, outputTokens: 500, iterations: 3 }\n\t// Issue #118: per-batch aggregate sits alongside the cumulative total.\n\tstate.batchUsage = { costUsd: 0.021, inputTokens: 500, outputTokens: 250, iterations: 1 }\n\treturn state\n}\n\ninterface Capture {\n\tout: string[]\n\terr: string[]\n\tio: { stdout: (t: string) => void; stderr: (t: string) => void }\n}\n\nfunction capture(): Capture {\n\tconst out: string[] = []\n\tconst err: string[] = []\n\treturn {\n\t\tout,\n\t\terr,\n\t\tio: {\n\t\t\tstdout: (t: string) => out.push(t),\n\t\t\tstderr: (t: string) => err.push(t),\n\t\t},\n\t}\n}\n\n// ─── parseStatusArgs ─────────────────────────────────────────────────────────\n\nasync function testParseStatusArgsDefaults(): Promise<void> {\n\tconst { options, error } = parseStatusArgs([\"--repo\", \"/tmp/repo\"])\n\tassert.equal(error, undefined)\n\tassert.equal(options.repo, \"/tmp/repo\")\n\tassert.equal(options.json, false)\n\tassert.equal(options.wait, false)\n\tassert.equal(options.timeoutMs, 2 * 60 * 60 * 1000, \"default timeout = 2h (watcher stall guard)\")\n\tassert.equal(options.pollIntervalMs, 5000, \"default poll = 5s (watcher write cadence)\")\n}\n\nasync function testParseStatusArgsCustomAndErrors(): Promise<void> {\n\tconst full = parseStatusArgs([\"--repo\", \"/tmp/repo\", \"--wait\", \"--json\", \"--timeout-ms\", \"60000\", \"--poll-interval-ms\", \"250\"])\n\tassert.equal(full.error, undefined)\n\tassert.equal(full.options.wait, true)\n\tassert.equal(full.options.json, true)\n\tassert.equal(full.options.timeoutMs, 60000)\n\tassert.equal(full.options.pollIntervalMs, 250)\n\n\t// `--flag=value` form works too.\n\tconst eq = parseStatusArgs([\"--repo=/tmp/repo\", \"--timeout-ms=1234\"])\n\tassert.equal(eq.error, undefined)\n\tassert.equal(eq.options.repo, \"/tmp/repo\")\n\tassert.equal(eq.options.timeoutMs, 1234)\n\n\tassert.ok(parseStatusArgs([\"--repo\"]).error?.includes(\"Missing value\"), \"missing --repo value errors\")\n\tassert.ok(parseStatusArgs([\"--timeout-ms\", \"abc\"]).error?.includes(\"positive integer\"), \"non-numeric timeout errors\")\n\tassert.ok(parseStatusArgs([\"--timeout-ms\", \"0\"]).error?.includes(\"positive integer\"), \"zero timeout errors\")\n\tassert.ok(parseStatusArgs([\"--nope\"]).error?.includes(\"Unknown\"), \"unknown flag errors\")\n\tassert.equal(parseStatusArgs([\"--help\"]).options.help, true)\n}\n\nasync function testParseStatusArgsOnGroupTerminal(): Promise<void> {\n\tconst ok = parseStatusArgs([\"--repo\", \"/tmp/repo\", \"--wait\", \"--on-group-terminal\", \"echo\"])\n\tassert.equal(ok.error, undefined)\n\tassert.equal(ok.options.onGroupTerminal, \"echo\")\n\n\t// The whole next arg is the command (no shell parsing later, so a\n\t// multi-word command like \"echo GOT:\" is kept intact).\n\tconst multiWord = parseStatusArgs([\"--repo\", \"/tmp/repo\", \"--on-group-terminal\", \"echo GOT:\"])\n\tassert.equal(multiWord.error, undefined)\n\tassert.equal(multiWord.options.onGroupTerminal, \"echo GOT:\")\n\n\tconst eq = parseStatusArgs([\"--repo=/tmp/repo\", \"--on-group-terminal=echo\"])\n\tassert.equal(eq.error, undefined)\n\tassert.equal(eq.options.onGroupTerminal, \"echo\", \"--flag=value form works\")\n\n\tconst missing = parseStatusArgs([\"--repo\", \"/tmp/repo\", \"--on-group-terminal\"])\n\tassert.ok(\n\t\tmissing.error?.includes(\"Missing value for --on-group-terminal\"),\n\t\t\"missing value errors (got: \" + String(missing.error) + \")\",\n\t)\n}\n\n// ─── One-shot status ─────────────────────────────────────────────────────────\n\nasync function testOneShotPrintsHumanSummary(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tsaveStateSync(path.join(repo, \".worktrees\", \".orchestrator-state.json\"), mixedState())\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo], cap.io)\n\n\t\tconst text = cap.out.join(\"\")\n\t\tassert.equal(code, 1, \"failed group present -> exit 1\")\n\t\tassert.ok(text.includes(\"── Orchestrator status ──\"), \"header line\")\n\t\tassert.ok(text.includes(`repo:       ${path.resolve(repo)}`), \"repo line\")\n\t\tassert.ok(text.includes(\"state file:\"), \"state file line\")\n\t\tassert.ok(text.includes(\"batch:      r1\"), \"batch line\")\n\t\tassert.ok(text.includes(\"total usage: $0.0420\"), \"round totals line\")\n\t\tassert.ok(text.includes(\"batch usage: $0.0210\"), \"issue #118 batch totals line\")\n\t\tassert.ok(text.includes(\"w-done\"), \"done group row\")\n\t\tassert.ok(text.includes(\"w-fail\"), \"failed group row\")\n\t\tassert.ok(text.includes(\"w-run\"), \"group row present\")\n\t\t// The fixture's w-run has no worktree on disk, so reconciliation must\n\t\t// surface it as \"orphaned\" — distinctly, not as a silent \"done\".\n\t\tassert.ok(text.includes(\"orphaned\"), \"orphaned status rendered for the worktree-less running group\")\n\t\tassert.ok(text.includes(\"3 groups: 1 done · 1 failed · 0 needs-human · 0 blocked · 0 running/spawned · 1 orphaned\"), \"counts line\")\n\t\tassert.ok(text.includes(\"reconciled: w-run (stale status patched from worktree markers)\"), \"reconciliation is surfaced in text\")\n\t\tassert.equal(cap.err.join(\"\"), \"\", \"no stderr on a healthy read\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testOneShotAllDoneExitsZero(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tlet state = defaultState(\"r1\")\n\t\tstate = updateGroup(state, \"w-done\", baseGroup({ name: \"w-done\", status: \"done\" }))\n\t\tsaveStateSync(path.join(repo, \".worktrees\", \".orchestrator-state.json\"), state)\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo], cap.io)\n\t\tassert.equal(code, 0, \"all done -> exit 0\")\n\t\tassert.ok(cap.out.join(\"\").includes(\"1 group: 1 done · 0 failed\"), \"singular counts line\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testOneShotJsonShape(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tsaveStateSync(path.join(repo, \".worktrees\", \".orchestrator-state.json\"), mixedState())\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo, \"--json\"], cap.io)\n\n\t\tassert.equal(code, 1, \"failed group present -> exit 1 even in --json mode\")\n\t\tconst parsed = JSON.parse(cap.out.join(\"\")) as OrchestratorState & { reconciled?: string[] }\n\t\tassert.equal(parsed.batch, \"r1\")\n\t\tassert.equal(parsed.groups.length, 3)\n\t\tassert.deepEqual(\n\t\t\tparsed.groups.map((g) => g.status).sort(),\n\t\t\t[\"done\", \"failed\", \"orphaned\"],\n\t\t\t\"--json passes the reconciled groups through (the worktree-less running group is orphaned)\",\n\t\t)\n\t\tassert.deepEqual(parsed.reconciled, [\"w-run\"], \"--json notes the group this call reconciled\")\n\t\tassert.ok(parsed.totalUsage && parsed.totalUsage.costUsd === 0.042, \"round totals preserved\")\n\t\tassert.ok(parsed.batchUsage && parsed.batchUsage.costUsd === 0.021, \"issue #118 batch totals preserved\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testOneShotInvalidStateFileExitsOne(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tawait fs.mkdir(path.dirname(statePath), { recursive: true })\n\t\tawait fs.writeFile(statePath, \"this is not json\", \"utf8\")\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo], cap.io)\n\t\tassert.equal(code, 1, \"unreadable state file -> exit 1\")\n\t\tassert.ok(cap.err.join(\"\").includes(\"cannot read state file\"), \"clear error on stderr\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testOneShotMissingRepoArgIsUsageError(): Promise<void> {\n\tconst cap = capture()\n\tconst code = await statusMain([], cap.io)\n\tassert.equal(code, 2, \"missing --repo -> usage error exit 2\")\n\tassert.ok(cap.err.join(\"\").includes(\"--repo <path> is required\"), \"usage error message\")\n\n\tconst bad = capture()\n\tconst code2 = await statusMain([\"--repo\", \"/tmp/x\", \"--bogus\"], bad.io)\n\tassert.equal(code2, 2, \"unknown flag -> usage error exit 2\")\n}\n\n// ─── waitForTerminalState (unit: fake state reader) ──────────────────────────\n\nasync function testWaitReturnsWhenAllGroupsDone(): Promise<void> {\n\tlet calls = 0\n\tconst readState = (): OrchestratorState => {\n\t\tcalls++\n\t\tif (calls < 3) {\n\t\t\treturn updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" }))\n\t\t}\n\t\treturn updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"done\" }))\n\t}\n\tconst result = await waitForTerminalState(\"\", { pollIntervalMs: 5, timeoutMs: 5000, readState })\n\n\tassert.equal(result.allDone, true)\n\tassert.equal(result.timedOut, false)\n\tassert.equal(result.state.groups[0].status, \"done\")\n\t// Floor of one poll interval (5ms): with a ms-resolution clock the expected\n\t// ~10ms of real time (2 polls x 5ms) can truncate to 9ms and flake; the\n\t// `calls >= 3` assertion below already proves it polled past the first read.\n\tassert.ok(result.elapsedMs >= 5, `waited for the transition, got ${result.elapsedMs}ms`)\n\tassert.ok(calls >= 3, `polled until terminal, got ${calls} reads`)\n}\n\nasync function testWaitTerminalButFailedIsNotAllDone(): Promise<void> {\n\tconst readState = (): OrchestratorState =>\n\t\tupdateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ name: \"w1\", status: \"failed\" }))\n\tconst result = await waitForTerminalState(\"\", { pollIntervalMs: 5, timeoutMs: 5000, readState })\n\n\tassert.equal(result.allDone, false, \"failed is terminal but NOT done\")\n\tassert.equal(result.timedOut, false)\n\tassert.equal(result.state.groups[0].status, \"failed\")\n}\n\nasync function testWaitBlockedIsNotTerminalAndTimesOut(): Promise<void> {\n\t// A \"blocked\" group is a decision-escalation wait state: --wait must keep\n\t// waiting (not exit early), so a never-unblocked round times out instead.\n\tconst readState = (): OrchestratorState =>\n\t\tupdateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"blocked\" }))\n\tconst result = await waitForTerminalState(\"\", { pollIntervalMs: 5, timeoutMs: 60, readState })\n\n\tassert.equal(result.timedOut, true, \"blocked is NOT terminal -> wait times out\")\n\tassert.equal(result.allDone, false)\n\tassert.equal(result.state.groups[0].status, \"blocked\")\n\tassert.ok(result.elapsedMs >= 60, `respected the timeout, got ${result.elapsedMs}ms`)\n}\n\nasync function testWaitEmptyStateReturnsImmediately(): Promise<void> {\n\t// An empty state file (round not started / wrong path) is nothing to wait\n\t// for — return immediately rather than hang until the timeout.\n\tconst result = await waitForTerminalState(\"\", { pollIntervalMs: 5, timeoutMs: 60000, readState: () => defaultState(\"r1\") })\n\tassert.equal(result.timedOut, false)\n\tassert.equal(result.allDone, false)\n\tassert.equal(result.state.groups.length, 0)\n\tassert.ok(result.elapsedMs < 1000, `returned promptly, got ${result.elapsedMs}ms`)\n}\n\n// ─── onGroupTerminal (Bug 2: per-group terminal notifications) ────────────────\n\nasync function testWaitOnGroupTerminalFiresOnGenuineTransition(): Promise<void> {\n\tlet calls = 0\n\tconst fired: Array<{ name: string; status: string }> = []\n\tconst readState = (): OrchestratorState => {\n\t\tcalls++\n\t\tif (calls < 3) {\n\t\t\treturn updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" }))\n\t\t}\n\t\treturn updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"failed\" }))\n\t}\n\tconst result = await waitForTerminalState(\"\", {\n\t\tpollIntervalMs: 5,\n\t\ttimeoutMs: 5000,\n\t\treadState,\n\t\tonGroupTerminal: (group) => {\n\t\t\tfired.push({ name: group.name, status: group.status })\n\t\t},\n\t})\n\n\tassert.deepEqual(fired, [{ name: \"w1\", status: \"failed\" }], \"fires exactly once, with name + terminal status\")\n\tassert.equal(result.allDone, false, \"failed is terminal but not done\")\n}\n\nasync function testWaitOnGroupTerminalSkipsAlreadyTerminalGroups(): Promise<void> {\n\tconst fired: string[] = []\n\tconst readState = (): OrchestratorState =>\n\t\tupdateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ name: \"w1\", status: \"done\" }))\n\tconst result = await waitForTerminalState(\"\", {\n\t\tpollIntervalMs: 5,\n\t\ttimeoutMs: 5000,\n\t\treadState,\n\t\tonGroupTerminal: (group) => {\n\t\t\tfired.push(`${group.name}:${group.status}`)\n\t\t},\n\t})\n\n\tassert.equal(result.allDone, true)\n\tassert.deepEqual(fired, [], \"groups already terminal when the wait started never fire\")\n}\n\nasync function testWaitOnGroupTerminalSkipsReconciliationOnlyChanges(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\t// The worker ALREADY finished before the wait started: the state file\n\t\t// still says \"running\", but ground truth (the worktree's .harness.done\n\t\t// marker + non-zero .harness.exit) says failed. The FIRST reconciliation\n\t\t// patches it to terminal BEFORE lastSeenStatus is seeded — the group\n\t\t// was always terminal, just stale in the file, so no genuine\n\t\t// transition exists and the callback must NOT fire.\n\t\tawait fs.mkdir(path.join(repo, \".worktrees\", \"w1\", \".harness.done\"), { recursive: true })\n\t\tawait fs.writeFile(path.join(repo, \".worktrees\", \"w1\", \".harness.exit\"), \"3\", \"utf8\")\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\n\t\tconst fired: string[] = []\n\t\tawait waitForTerminalState(statePath, {\n\t\t\tpollIntervalMs: 5,\n\t\t\ttimeoutMs: 5000,\n\t\t\treconcile: (state) => {\n\t\t\t\tconst r = reconcileGroups(state, repo)\n\t\t\t\tif (r.reconciled.length > 0) {\n\t\t\t\t\tsaveStateSync(statePath, r.state)\n\t\t\t\t}\n\t\t\t\treturn r\n\t\t\t},\n\t\t\tonGroupTerminal: (group) => {\n\t\t\t\tfired.push(`${group.name}:${group.status}`)\n\t\t\t},\n\t\t})\n\t\tassert.deepEqual(fired, [], \"reconciliation-only changes (stale running -> failed) never fire\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\n// ─── statusMain --wait (end-to-end via the real state file) ─────────────────\n\nasync function testWaitAgainstRealFileTransitionsToDone(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\t// The worktree must EXIST so reconciliation keeps the group genuinely\n\t\t// running (a missing worktree would reconcile it to \"orphaned\"\n\t\t// instantly and the wait would not be waiting at all).\n\t\tawait fs.mkdir(path.join(repo, \".worktrees\", \"w1\"), { recursive: true })\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\n\t\tconst cap = capture()\n\t\tconst waitPromise = statusMain([\"--repo\", repo, \"--wait\", \"--timeout-ms\", \"5000\", \"--poll-interval-ms\", \"25\"], cap.io)\n\n\t\t// Transition the state file partway through the wait (the watcher\n\t\t// would do this; here the test plays the writer).\n\t\tawait new Promise((resolve) => setTimeout(resolve, 150))\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"done\" })))\n\n\t\tconst code = await waitPromise\n\t\tconst text = cap.out.join(\"\")\n\n\t\tassert.equal(code, 0, \"clean finish -> exit 0\")\n\t\tassert.ok(text.includes(\"(waited\"), \"duration is reported\")\n\t\tassert.ok(text.includes(\"verdict: 1/1 groups done, 0 failed\"), \"one-line verdict\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testWaitTimesOutWithClearVerdict(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\t// Two groups: one done, one running forever. The running group's\n\t\t// worktree must EXIST (no .harness.done) so reconciliation leaves it\n\t\t// running and the wait actually times out. baseGroup's default\n\t\t// worktree is \".worktrees/w1\", so pin it explicitly.\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tlet state = updateGroup(defaultState(\"r1\"), \"w-done\", baseGroup({ name: \"w-done\", status: \"done\" }))\n\t\tstate = updateGroup(\n\t\t\tstate,\n\t\t\t\"w-run\",\n\t\t\tbaseGroup({ name: \"w-run\", status: \"running\", worktree: \".worktrees/w-run\" }),\n\t\t)\n\t\tsaveStateSync(statePath, state)\n\t\tawait fs.mkdir(path.join(repo, \".worktrees\", \"w-run\"), { recursive: true })\n\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo, \"--wait\", \"--timeout-ms\", \"100\", \"--poll-interval-ms\", \"15\"], cap.io)\n\n\t\tassert.equal(code, 1, \"timeout -> exit 1\")\n\t\tassert.ok(cap.out.join(\"\").includes(\"verdict: timed out after 1 of 2 groups done\"), \"timeout verdict names progress\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testWaitJsonCarriesVerdictFields(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"done\" })))\n\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo, \"--wait\", \"--json\", \"--timeout-ms\", \"1000\"], cap.io)\n\n\t\tassert.equal(code, 0, \"all done -> exit 0\")\n\t\tconst parsed = JSON.parse(cap.out.join(\"\")) as Record<string, unknown> & { allDone: boolean; timedOut: boolean; verdict: string }\n\t\tassert.equal(parsed.allDone, true, \"top-level allDone flag\")\n\t\tassert.equal(parsed.timedOut, false, \"top-level timedOut flag\")\n\t\tassert.equal(parsed.verdict, \"1/1 groups done, 0 failed\", \"top-level verdict line\")\n\t\tassert.ok(Array.isArray(parsed.groups), \"state shape preserved alongside the verdict fields\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testWaitOnGroupTerminalHookSpawnsCommand(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\t// Worktree must EXIST so reconciliation keeps the group genuinely\n\t\t// running while the wait polls (a missing worktree would reconcile it\n\t\t// to orphaned instantly and no live transition would ever be observed).\n\t\tawait fs.mkdir(path.join(repo, \".worktrees\", \"w1\"), { recursive: true })\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\n\t\t// The hook: a tiny script that records its two positional args (group\n\t\t// name + terminal status) to a log file.\n\t\tconst hookLog = path.join(repo, \"hook-args.log\")\n\t\tconst hook = path.join(repo, \"hook.sh\")\n\t\tawait fs.writeFile(hook, `#!/bin/sh\\nprintf '%s %s\\\\n' \"$1\" \"$2\" >> \"${hookLog}\"\\n`, \"utf-8\")\n\t\tawait fs.chmod(hook, 0o755)\n\n\t\tconst cap = capture()\n\t\tconst waitPromise = statusMain(\n\t\t\t[\"--repo\", repo, \"--wait\", \"--timeout-ms\", \"5000\", \"--poll-interval-ms\", \"25\", \"--on-group-terminal\", hook],\n\t\t\tcap.io,\n\t\t)\n\n\t\t// Transition the state file partway through the wait (the watcher\n\t\t// would do this; here the test plays the writer).\n\t\tawait new Promise((resolve) => setTimeout(resolve, 150))\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"done\" })))\n\n\t\tconst code = await waitPromise\n\t\tassert.equal(code, 0, \"clean finish -> exit 0\")\n\t\tconst log = await fs.readFile(hookLog, \"utf-8\")\n\t\tassert.ok(log.trim() === \"w1 done\", `hook received <group-name> <status>, got: ${JSON.stringify(log)}`)\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\n// ─── Read-side reconciliation (one-shot + --wait) ────────────────────────────\n\n/**\n\t* Create `<repo>/.worktrees/<name>`; when `exitCode` is given also drop the\n\t* `.harness.done` marker dir + `.harness.exit` file the watcher/run-worker.sh\n\t* would have left behind. No exitCode → worktree exists with NO marker (a\n\t* genuinely still-running worker).\n\t*/\nasync function makeWorktree(repo: string, name: string, exitCode?: number): Promise<void> {\n\tconst wt = path.join(repo, \".worktrees\", name)\n\tawait fs.mkdir(wt, { recursive: true })\n\tif (exitCode === undefined) {\n\t\treturn\n\t}\n\t// Order matters: run-worker.sh writes .harness.exit FIRST, then creates\n\t// the .harness.done marker dir (the done marker is the atomic last write\n\t// — see scripts/run-worker.sh:222-223). Reverse the order and a reader\n\t// can observe done-without-exit, which reconciles to \"failed\".\n\tawait fs.writeFile(path.join(wt, \".harness.exit\"), String(exitCode), \"utf8\")\n\tawait fs.mkdir(path.join(wt, \".harness.done\"), { recursive: true })\n}\n\nasync function testOneShotReconcilesDoneFromMarkersAndPersists(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\t\tawait makeWorktree(repo, \"w1\", 0)\n\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo], cap.io)\n\n\t\tassert.equal(code, 0, \"reconciled to done -> exit 0\")\n\t\tassert.ok(cap.out.join(\"\").includes(\"w1\"), \"group row present\")\n\t\t// The patch must be persisted back to the state file, not just\n\t\t// applied to the in-memory copy.\n\t\tconst onDisk = loadStateSync(statePath)\n\t\tassert.equal(onDisk.groups[0].status, \"done\", \"state file updated to done\")\n\t\tassert.equal(onDisk.groups[0].exit_code, 0, \"exit_code recorded in the state file\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testOneShotReconcilesFailedFromNonZeroExit(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\t\tawait makeWorktree(repo, \"w1\", 3)\n\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo], cap.io)\n\n\t\tassert.equal(code, 1, \"reconciled to failed -> exit 1\")\n\t\tconst onDisk = loadStateSync(statePath)\n\t\tassert.equal(onDisk.groups[0].status, \"failed\", \"state file updated to failed\")\n\t\tassert.equal(onDisk.groups[0].exit_code, 3, \"non-zero exit_code recorded\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testOneShotReconcilesOrphanedDistinctly(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\t\t// No worktree dir at all → nothing to wait for, outcome unknowable.\n\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo], cap.io)\n\n\t\tassert.equal(code, 1, \"orphaned is a needs-attention outcome -> exit 1\")\n\t\tconst text = cap.out.join(\"\")\n\t\tassert.ok(text.includes(\"orphaned\"), \"text renders the orphaned status\")\n\t\tassert.ok(text.includes(\"1 group: 0 done · 0 failed · 0 needs-human · 0 blocked · 0 running/spawned · 1 orphaned\"), \"counts line keeps orphaned distinct from done\")\n\t\tassert.ok(!/1 group: 1 done/.test(text), \"orphaned is never reported as done\")\n\n\t\tconst onDisk = loadStateSync(statePath)\n\t\tassert.equal(onDisk.groups[0].status, \"orphaned\", \"state file updated to orphaned\")\n\n\t\t// --json on a FRESH stale state: distinct status + reconciled list.\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\t\tconst capJson = capture()\n\t\tawait statusMain([\"--repo\", repo, \"--json\"], capJson.io)\n\t\tconst parsed = JSON.parse(capJson.out.join(\"\")) as OrchestratorState & { reconciled?: string[] }\n\t\tassert.equal(parsed.groups[0].status, \"orphaned\", \"json status is orphaned, not done\")\n\t\tassert.deepEqual(parsed.reconciled, [\"w1\"], \"json notes the group this call reconciled\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testOneShotLeavesRunningGroupWithLiveWorktreeAlone(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\t\t// Worktree exists but has NO .harness.done marker → genuinely running.\n\t\tawait makeWorktree(repo, \"w1\")\n\n\t\tconst cap = capture()\n\t\tconst code = await statusMain([\"--repo\", repo], cap.io)\n\n\t\tassert.equal(code, 0, \"running-only state -> exit 0\")\n\t\tassert.ok(cap.out.join(\"\").includes(\"1 running/spawned\"), \"group still reported running\")\n\t\tconst onDisk = loadStateSync(statePath)\n\t\tassert.equal(onDisk.groups[0].status, \"running\", \"reconciliation must not touch a live worktree\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testWaitReconcilesStaleGroupPromptly(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tlet state = updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" }))\n\t\tstate = updateGroup(state, \"w2\", baseGroup({ name: \"w2\", status: \"done\" }))\n\t\tsaveStateSync(statePath, state)\n\t\t// w1 is stale-but-reconcilable: its worktree still exists with a real\n\t\t// .harness.done marker, it's just that nobody updated the state file.\n\t\tawait makeWorktree(repo, \"w1\", 0)\n\n\t\tconst t0 = Date.now()\n\t\tconst cap = capture()\n\t\tconst code = await statusMain(\n\t\t\t[\"--repo\", repo, \"--wait\", \"--json\", \"--timeout-ms\", \"5000\", \"--poll-interval-ms\", \"50\"],\n\t\t\tcap.io,\n\t\t)\n\t\tconst elapsed = Date.now() - t0\n\n\t\tassert.equal(code, 0, \"reconciled to done + all done -> exit 0\")\n\t\tconst parsed = JSON.parse(cap.out.join(\"\")) as OrchestratorState & {\n\t\t\tallDone: boolean\n\t\t\ttimedOut: boolean\n\t\t\tverdict: string\n\t\t\treconciled?: string[]\n\t\t}\n\t\tassert.equal(parsed.allDone, true)\n\t\tassert.equal(parsed.timedOut, false)\n\t\tassert.equal(parsed.verdict, \"2/2 groups done, 0 failed\")\n\t\tassert.deepEqual(parsed.reconciled, [\"w1\"], \"wait reports the reconciled group\")\n\t\tassert.ok(elapsed < 2000, `returned promptly instead of waiting the timeout (${elapsed}ms)`)\n\n\t\t// Issue #116: with NO live watcher (no heartbeat file), the wait is\n\t\t// the only writer and its reconcile patch must still persist.\n\t\tconst onDisk = loadStateSync(statePath)\n\t\tassert.equal(onDisk.groups[0].status, \"done\", \"wait persisted the reconcile with no live watcher\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\n/**\n * Issue #116: `status --wait` running CONCURRENTLY with a live orchestrate\n * round used to persist its read-side reconciliation, pre-empting the\n * watcher (which then short-circuited the group and silently skipped log\n * analysis + the automated review). With the watcher's heartbeat present,\n * the wait must reconcile IN MEMORY only — the shared state file must keep\n * saying \"running\" so the watcher still owns the done transition.\n */\nasync function testWaitDoesNotPersistReconcileWhenWatcherHeartbeatFresh(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\t\tawait makeWorktree(repo, \"w1\", 0)\n\t\t// A live watcher owns the state: its heartbeat file is fresh.\n\t\tawait fs.writeFile(`${statePath}.watcher`, \"99999\", \"utf8\")\n\n\t\tconst cap = capture()\n\t\tconst code = await statusMain(\n\t\t\t[\"--repo\", repo, \"--wait\", \"--json\", \"--timeout-ms\", \"5000\", \"--poll-interval-ms\", \"25\"],\n\t\t\tcap.io,\n\t\t)\n\n\t\tassert.equal(code, 0, \"in-memory reconcile to done -> all done -> exit 0\")\n\t\tconst parsed = JSON.parse(cap.out.join(\"\")) as OrchestratorState & { reconciled?: string[] }\n\t\tassert.equal(parsed.groups[0].status, \"done\", \"the wait's REPORTED state reflects the in-memory reconcile\")\n\t\tassert.deepEqual(parsed.reconciled, [\"w1\"], \"wait still reports the group it reconciled\")\n\t\t// The persisted file must be untouched — the watcher owns the done\n\t\t// transition and must still observe the group as running.\n\t\tconst onDisk = loadStateSync(statePath)\n\t\tassert.equal(onDisk.groups[0].status, \"running\", \"no persist while a live watcher owns the state\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\n/** A STALE heartbeat means the watcher is gone — the wait may persist again. */\nasync function testWaitPersistsWhenWatcherHeartbeatStale(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\t\tawait makeWorktree(repo, \"w1\", 0)\n\t\t// A heartbeat from 10 minutes ago: the watcher is dead; the wait is\n\t\t// the only writer and must patch the stale entry back.\n\t\tconst stale = new Date(Date.now() - 10 * 60 * 1000)\n\t\tawait fs.writeFile(`${statePath}.watcher`, \"99999\", \"utf8\")\n\t\tconst { utimes } = await import(\"node:fs/promises\")\n\t\tawait utimes(`${statePath}.watcher`, stale, stale)\n\n\t\tconst cap = capture()\n\t\tconst code = await statusMain(\n\t\t\t[\"--repo\", repo, \"--wait\", \"--json\", \"--timeout-ms\", \"5000\", \"--poll-interval-ms\", \"25\"],\n\t\t\tcap.io,\n\t\t)\n\n\t\tassert.equal(code, 0, \"all done -> exit 0\")\n\t\tconst onDisk = loadStateSync(statePath)\n\t\tassert.equal(onDisk.groups[0].status, \"done\", \"stale watcher heartbeat -> wait persists the reconcile\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\n/**\n * Issue #116 (rework cycle 1): a watcher-less --wait with a worker that\n * finishes MID-wait must still persist the reconciled done transition. The\n * first #116 fix made the wait write its own heartbeat (<statePath>.watcher\n * = its own PID) on every poll, and liveWatcher() treated ANY fresh\n * heartbeat as a live watcher — so from the second poll onward the wait\n * believed a watcher owned the state, skipped saveStateSync, exited 0\n * reporting \"done\", and left the on-disk state stuck on \"running\" forever\n * (no watcher existed to ever persist it). A fresh heartbeat only counts\n * when it carries a DIFFERENT process's PID.\n */\nasync function testWaitPersistsMidWaitReconcileWithNoWatcher(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\t// Genuinely running at wait-start: worktree exists, NO .harness.done\n\t\t// marker yet (a missing worktree would reconcile to orphaned instantly).\n\t\tawait fs.mkdir(path.join(repo, \".worktrees\", \"w1\"), { recursive: true })\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\n\t\tconst cap = capture()\n\t\tconst waitPromise = statusMain(\n\t\t\t[\"--repo\", repo, \"--wait\", \"--json\", \"--timeout-ms\", \"5000\", \"--poll-interval-ms\", \"25\"],\n\t\t\tcap.io,\n\t\t)\n\n\t\t// Let the wait poll a few times — with the regression, its own\n\t\t// heartbeat is now fresh and it would wrongly see a \"live watcher\".\n\t\tawait new Promise((resolve) => setTimeout(resolve, 150))\n\t\t// The worker finishes mid-wait: drop the real completion markers.\n\t\t// Exit first, then the done marker (run-worker.sh order).\n\t\tawait fs.writeFile(path.join(repo, \".worktrees\", \"w1\", \".harness.exit\"), \"0\", \"utf8\")\n\t\tawait fs.mkdir(path.join(repo, \".worktrees\", \"w1\", \".harness.done\"), { recursive: true })\n\n\t\tconst code = await waitPromise\n\t\tassert.equal(code, 0, \"worker finished mid-wait -> exit 0\")\n\t\tconst parsed = JSON.parse(cap.out.join(\"\")) as OrchestratorState & { allDone: boolean; timedOut: boolean }\n\t\tassert.equal(parsed.allDone, true, \"wait reports all done\")\n\t\tassert.equal(parsed.timedOut, false, \"wait did not time out\")\n\t\t// The on-disk state MUST be done: with no watcher, the wait is the\n\t\t// only writer, and a watcher-less round depends on this persist.\n\t\tconst onDisk = loadStateSync(statePath)\n\t\tassert.equal(onDisk.groups[0].status, \"done\", \"mid-wait reconcile persisted with no live watcher\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\n/**\n * Issue #116 (rework cycle 2): the exact repro that reopened the bug. A\n * fresh heartbeat from a DIFFERENT process (PID 99999 = live watcher) is\n * present when the wait starts, and the worker finishes MID-wait (markers\n * dropped after the wait's first poll). The cycle-1 fix reintroduced the\n * bug by having the wait stamp its own PID into the shared heartbeat file\n * every poll: from the second poll onward the wait read its OWN PID,\n * concluded \"no live watcher\", and persisted the done reconcile on disk —\n * the watcher's next poll then short-circuited the group and silently\n * skipped log analysis + review. The wait must NEVER write the heartbeat\n * file: the live watcher's fresh heartbeat (different PID) must keep the\n * on-disk state on \"running\" so the watcher still owns the done transition.\n *\n * Staleness is judged against the WATCHER's heartbeat cadence\n * (DEFAULT_POLL_INTERVAL_MS = 5s), not the wait's own poll interval — a\n * fast-polling wait must not declare a live watcher dead between the\n * watcher's own refreshes.\n */\nasync function testWaitMidWaitReconcileWithLiveWatcherDoesNotPersist(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\t// Genuinely running at wait-start: worktree exists, NO .harness.done\n\t\t// marker yet (a missing worktree would reconcile to orphaned instantly).\n\t\tawait fs.mkdir(path.join(repo, \".worktrees\", \"w1\"), { recursive: true })\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\t\t// A live watcher owns the state: its heartbeat is fresh AND carries a\n\t\t// DIFFERENT PID. The wait must leave this file untouched.\n\t\tawait fs.writeFile(`${statePath}.watcher`, \"99999\", \"utf8\")\n\n\t\tconst cap = capture()\n\t\tconst waitPromise = statusMain(\n\t\t\t[\"--repo\", repo, \"--wait\", \"--json\", \"--timeout-ms\", \"5000\", \"--poll-interval-ms\", \"25\"],\n\t\t\tcap.io,\n\t\t)\n\n\t\t// Let the wait poll a few times first — with the cycle-1 regression\n\t\t// its own heartbeat had already clobbered the live watcher's by now.\n\t\tawait new Promise((resolve) => setTimeout(resolve, 150))\n\t\t// The worker finishes mid-wait: drop the real completion markers.\n\t\t// Exit first, then the done marker (run-worker.sh order).\n\t\tawait fs.writeFile(path.join(repo, \".worktrees\", \"w1\", \".harness.exit\"), \"0\", \"utf8\")\n\t\tawait fs.mkdir(path.join(repo, \".worktrees\", \"w1\", \".harness.done\"), { recursive: true })\n\n\t\tconst code = await waitPromise\n\t\tassert.equal(code, 0, \"worker finished mid-wait -> exit 0\")\n\t\tconst parsed = JSON.parse(cap.out.join(\"\")) as OrchestratorState & { allDone: boolean; timedOut: boolean }\n\t\tassert.equal(parsed.allDone, true, \"wait reports all done (in-memory reconcile)\")\n\t\tassert.equal(parsed.timedOut, false, \"wait did not time out\")\n\t\t// The on-disk state MUST stay running: the live watcher owns the done\n\t\t// transition and must still observe the group as running so its log\n\t\t// analysis + automated review fire.\n\t\tconst onDisk = loadStateSync(statePath)\n\t\tassert.equal(onDisk.groups[0].status, \"running\", \"no persist while a live watcher owns the state\")\n\t\t// The live watcher's heartbeat must be untouched by the wait.\n\t\tconst heartbeatPid = await fs.readFile(`${statePath}.watcher`, \"utf8\")\n\t\tassert.equal(heartbeatPid, \"99999\", \"wait never writes the shared watcher heartbeat file\")\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\nasync function testWaitTreatsOrphanedAsTerminal(): Promise<void> {\n\tconst repo = await tmpRepo()\n\ttry {\n\t\tconst statePath = path.join(repo, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, updateGroup(defaultState(\"r1\"), \"w1\", baseGroup({ status: \"running\" })))\n\t\t// No worktree → reconciled to orphaned on the first poll → terminal.\n\n\t\tconst t0 = Date.now()\n\t\tconst cap = capture()\n\t\tconst code = await statusMain(\n\t\t\t[\"--repo\", repo, \"--wait\", \"--timeout-ms\", \"5000\", \"--poll-interval-ms\", \"50\"],\n\t\t\tcap.io,\n\t\t)\n\t\tconst elapsed = Date.now() - t0\n\n\t\tassert.equal(code, 1, \"orphaned is terminal but NOT done -> exit 1\")\n\t\tconst text = cap.out.join(\"\")\n\t\tassert.ok(text.includes(\"verdict: all 1 group terminal, but 1 orphaned\"), \"verdict names the orphaned group\")\n\t\tassert.ok(!text.includes(\"timed out\"), \"did not wait out the full timeout\")\n\t\tassert.ok(elapsed < 2000, `returned promptly instead of waiting the timeout (${elapsed}ms)`)\n\t} finally {\n\t\tawait fs.rm(repo, { recursive: true, force: true })\n\t}\n}\n\n// ─── Runner ──────────────────────────────────────────────────────────────────\n\nconst tests: Array<[string, () => Promise<void>]> = [\n\t[\"parseStatusArgs: defaults\", testParseStatusArgsDefaults],\n\t[\"parseStatusArgs: custom values, =form, error cases\", testParseStatusArgsCustomAndErrors],\n\t[\"one-shot prints the human summary and exits 1 on a failed group\", testOneShotPrintsHumanSummary],\n\t[\"one-shot all-done exits 0\", testOneShotAllDoneExitsZero],\n\t[\"one-shot --json passes the raw state through\", testOneShotJsonShape],\n\t[\"one-shot invalid state file exits 1 with a clear error\", testOneShotInvalidStateFileExitsOne],\n\t[\"one-shot missing --repo / unknown flag are usage errors (exit 2)\", testOneShotMissingRepoArgIsUsageError],\n\t[\"wait returns once every group is done, not before\", testWaitReturnsWhenAllGroupsDone],\n\t[\"wait: terminal-but-failed is not allDone\", testWaitTerminalButFailedIsNotAllDone],\n\t[\"wait: blocked is NOT terminal and times out\", testWaitBlockedIsNotTerminalAndTimesOut],\n\t[\"wait: empty state returns immediately\", testWaitEmptyStateReturnsImmediately],\n\t[\"wait against the real state file transitions to done\", testWaitAgainstRealFileTransitionsToDone],\n\t[\"wait times out with a clear verdict and exit 1\", testWaitTimesOutWithClearVerdict],\n\t[\"wait --json carries allDone/timedOut/verdict fields\", testWaitJsonCarriesVerdictFields],\n\t[\"one-shot reconciles done from .harness markers and persists\", testOneShotReconcilesDoneFromMarkersAndPersists],\n\t[\"one-shot reconciles failed from a non-zero .harness.exit\", testOneShotReconcilesFailedFromNonZeroExit],\n\t[\"one-shot reconciles orphaned and renders it distinctly (text + json)\", testOneShotReconcilesOrphanedDistinctly],\n\t[\"one-shot leaves a running group with a live worktree alone\", testOneShotLeavesRunningGroupWithLiveWorktreeAlone],\n\t[\"wait reconciles a stale-but-reconcilable group promptly (and persists without a watcher)\", testWaitReconcilesStaleGroupPromptly],\n\t[\"wait does NOT persist reconcile while a watcher heartbeat is fresh (issue #116)\", testWaitDoesNotPersistReconcileWhenWatcherHeartbeatFresh],\n\t[\"wait persists reconcile again once the watcher heartbeat is stale\", testWaitPersistsWhenWatcherHeartbeatStale],\n\t[\"wait persists a mid-wait reconcile with no watcher (issue #116 rework)\", testWaitPersistsMidWaitReconcileWithNoWatcher],\n\t[\"wait never persists mid-wait reconcile with a live watcher (issue #116 rework 2)\", testWaitMidWaitReconcileWithLiveWatcherDoesNotPersist],\n\t[\"wait treats orphaned as terminal and returns promptly\", testWaitTreatsOrphanedAsTerminal],\n]\n\nasync function main(): Promise<void> {\n\tlet failed = 0\n\tfor (const [name, fn] of tests) {\n\t\ttry {\n\t\t\tawait fn()\n\t\t\tconsole.log(`  ok   ${name}`)\n\t\t} catch (err) {\n\t\t\tfailed++\n\t\t\tconsole.error(`  FAIL ${name}`)\n\t\t\tconsole.error(err instanceof Error ? err.stack ?? err.message : String(err))\n\t\t}\n\t}\n\tif (failed > 0) {\n\t\tconsole.error(`\\n${failed} test(s) failed`)\n\t\tprocess.exit(1)\n\t}\n\tconsole.log(`\\nAll ${tests.length} status-cli tests passed`)\n}\n\nmain().catch((err) => {\n\tconsole.error(\"Test runner crashed:\", err)\n\tprocess.exit(1)\n})"},{"path":"src/orchestrator/__tests__/watch.test.ts","source":"/**\n * Unit tests for src/orchestrator/watch.ts — worktree completion polling,\n * focused on the decision-escalation \"blocked\" status transition\n * (workstream 2): `.harness.needs-decision` appears -> group status\n * \"blocked\" with the question recorded -> marker removed -> status flows\n * back to \"running\". Plain assert-based script (no framework, no network),\n * run via `npm test` -> `tsx src/orchestrator/__tests__/watch.test.ts`.\n */\n\nimport assert from \"node:assert/strict\"\nimport * as fs from \"node:fs/promises\"\nimport * as os from \"node:os\"\nimport * as path from \"node:path\"\nimport { spawnSync } from \"node:child_process\"\n\nimport {\n\tcomputeBatchUsage,\n\tcomputeTotalUsage,\n\tinspectGroup,\n\tisIterationExhaustion,\n\tisProviderFailure,\n\ttailLog,\n\twatchGroups,\n\tDEFAULT_STALL_TIMEOUT_MS,\n} from \"../watch.js\"\nimport {\n\tdefaultState,\n\tloadStateSync,\n\tsaveStateSync,\n\tupdateGroup,\n\ttype OrchestratorGroup,\n\ttype OrchestratorState,\n} from \"../state.js\"\n\nasync function tmpRepo(): Promise<string> {\n\treturn fs.mkdtemp(path.join(os.tmpdir(), \"headlesscode-watch-blocked-\"))\n}\n\nfunction baseGroup(overrides: Partial<OrchestratorGroup> = {}): OrchestratorGroup {\n\treturn {\n\t\tname: \"w1\",\n\t\tworktree: \".worktrees/w1\",\n\t\tstatus: \"running\",\n\t\tspawned: new Date().toISOString(),\n\t\t...overrides,\n\t}\n}\n\n// ─── inspectGroup: pure unit coverage ───────────────────────────────────────\n\nasync function testInspectGroupDetectsNeedsDecisionMarker(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\tawait fs.writeFile(\n\t\t\tpath.join(wtPath, \".harness.needs-decision\"),\n\t\t\tJSON.stringify({\n\t\t\t\tquestion: \"Which auth strategy should I use?\",\n\t\t\t\tsuggestions: [\"JWT\", \"session cookies\"],\n\t\t\t\taskedAt: \"2026-08-01T00:00:00.000Z\",\n\t\t\t}),\n\t\t\t\"utf-8\",\n\t\t)\n\n\t\tconst group = baseGroup()\n\t\tconst patch = inspectGroup(repoRoot, group, Date.now(), DEFAULT_STALL_TIMEOUT_MS)\n\n\t\tassert.ok(patch, \"a needs-decision marker must produce a patch\")\n\t\tassert.equal(patch?.status, \"blocked\")\n\t\tassert.equal(patch?.blocked?.question, \"Which auth strategy should I use?\")\n\t\tassert.deepEqual(patch?.blocked?.suggestions, [\"JWT\", \"session cookies\"])\n\t\tassert.equal(patch?.blocked?.askedAt, \"2026-08-01T00:00:00.000Z\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\nasync function testInspectGroupNoChangeWhenAlreadyBlockedOnSameQuestion(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\tconst decision = { question: \"Same question?\", askedAt: \"2026-08-01T00:00:00.000Z\" }\n\t\tawait fs.writeFile(path.join(wtPath, \".harness.needs-decision\"), JSON.stringify(decision), \"utf-8\")\n\n\t\tconst group = baseGroup({ status: \"blocked\", blocked: decision })\n\t\tconst patch = inspectGroup(repoRoot, group, Date.now(), DEFAULT_STALL_TIMEOUT_MS)\n\t\tassert.equal(patch, undefined, \"no state churn when already blocked on the identical question\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\nasync function testInspectGroupFlowsBackToRunningWhenMarkerRemoved(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\t// No .harness.needs-decision file present -> the worker resumed.\n\n\t\tconst group = baseGroup({ status: \"blocked\", blocked: { question: \"old question\" } })\n\t\tconst patch = inspectGroup(repoRoot, group, Date.now(), DEFAULT_STALL_TIMEOUT_MS)\n\n\t\tassert.ok(patch, \"marker gone while blocked must produce a patch\")\n\t\tassert.equal(patch?.status, \"running\")\n\t\tassert.equal(patch?.blocked, undefined, \"blocked field must be cleared\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\nasync function testBlockedGroupIsExemptFromStallGuard(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\tawait fs.writeFile(\n\t\t\tpath.join(wtPath, \".harness.needs-decision\"),\n\t\t\tJSON.stringify({ question: \"still waiting\", askedAt: \"2020-01-01T00:00:00.000Z\" }),\n\t\t\t\"utf-8\",\n\t\t)\n\n\t\t// Spawned far longer ago than the stall timeout, and no pid file at all\n\t\t// (which would normally mean \"stalled\" per the existing guard) — but a\n\t\t// present needs-decision marker must win: status stays \"blocked\", never\n\t\t// \"failed\"/\"stalled\".\n\t\tconst longAgo = new Date(Date.now() - DEFAULT_STALL_TIMEOUT_MS * 10).toISOString()\n\t\tconst group = baseGroup({ spawned: longAgo })\n\t\tconst patch = inspectGroup(repoRoot, group, Date.now(), DEFAULT_STALL_TIMEOUT_MS)\n\n\t\tassert.ok(patch)\n\t\tassert.equal(patch?.status, \"blocked\", \"a blocked group must never be marked stalled/failed by the stall guard\")\n\t\tassert.equal(patch?.stalled, undefined)\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n// ─── watchGroups: end-to-end blocked -> running transition ─────────────────\n\nasync function testWatchGroupsBlockedThenUnblockedFlow(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\tconst statePath = path.join(repoRoot, \".worktrees\", \".orchestrator-state.json\")\n\n\t\tconst initial: OrchestratorState = { ...defaultState(\"round-1\"), groups: [baseGroup()] }\n\t\tsaveStateSync(statePath, initial)\n\n\t\tconst needsDecisionPath = path.join(wtPath, \".harness.needs-decision\")\n\t\tawait fs.writeFile(\n\t\t\tneedsDecisionPath,\n\t\t\tJSON.stringify({ question: \"Deploy to staging first?\", askedAt: new Date().toISOString() }),\n\t\t\t\"utf-8\",\n\t\t)\n\n\t\tconst controller = new AbortController()\n\t\tconst seenStatuses: string[] = []\n\t\tconst watchPromise = watchGroups({\n\t\t\trepoRoot,\n\t\t\tstatePath,\n\t\t\tpollIntervalMs: 20,\n\t\t\t// This test asserts the persisted status flow, not the new stderr\n\t\t\t// signal — silence it so the suite output stays clean.\n\t\t\tstderrWriter: () => {},\n\t\t\tonGroupUpdate: async (group) => {\n\t\t\t\tseenStatuses.push(group.status)\n\t\t\t\tif (group.status === \"blocked\") {\n\t\t\t\t\t// Simulate scripts/headlesscode-answer.sh + the worker resuming:\n\t\t\t\t\t// remove the needs-decision marker so the next poll sees it gone.\n\t\t\t\t\t// Awaited so the next poll iteration never races the unlink.\n\t\t\t\t\tawait fs.unlink(needsDecisionPath).catch(() => {})\n\t\t\t\t} else if (group.status === \"running\") {\n\t\t\t\t\t// Worker finished for real now -> terminate the watch loop.\n\t\t\t\t\tawait fs.mkdir(path.join(wtPath, \".harness.done\"))\n\t\t\t\t\tawait fs.writeFile(path.join(wtPath, \".harness.exit\"), \"0\", \"utf-8\")\n\t\t\t\t}\n\t\t\t},\n\t\t\tsignal: controller.signal,\n\t\t})\n\n\t\tconst summary = await watchPromise\n\t\tassert.deepEqual(seenStatuses, [\"blocked\", \"running\", \"done\"])\n\t\tassert.equal(summary.allTerminal, true)\n\t\tconst finalGroup = summary.state.groups.find((g) => g.name === \"w1\")\n\t\tassert.equal(finalGroup?.status, \"done\")\n\t\tassert.equal(finalGroup?.blocked, undefined, \"blocked field cleared once resolved\")\n\n\t\tconst persisted = loadStateSync(statePath)\n\t\tassert.equal(persisted.groups[0].status, \"done\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n// ─── watchGroups: proactive status-change stderr signal (gap 2) ─────────────\n\nasync function testWatchGroupsPrintsBlockedTransitionToStderr(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\tconst statePath = path.join(repoRoot, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, { ...defaultState(\"round-1\"), groups: [baseGroup()] })\n\t\tawait fs.writeFile(\n\t\t\tpath.join(wtPath, \".harness.needs-decision\"),\n\t\t\tJSON.stringify({ question: \"Which auth strategy should I use?\", askedAt: new Date().toISOString() }),\n\t\t\t\"utf-8\",\n\t\t)\n\n\t\tconst controller = new AbortController()\n\t\tconst lines: string[] = []\n\t\tawait watchGroups({\n\t\t\trepoRoot,\n\t\t\tstatePath,\n\t\t\tpollIntervalMs: 20,\n\t\t\tstderrWriter: (text) => lines.push(text),\n\t\t\tonGroupUpdate: async (group) => {\n\t\t\t\tif (group.status === \"blocked\") {\n\t\t\t\t\t// Stop the loop once the transition has been observed.\n\t\t\t\t\tcontroller.abort()\n\t\t\t\t}\n\t\t\t},\n\t\t\tsignal: controller.signal,\n\t\t})\n\n\t\tconst joined = lines.join(\"\")\n\t\tassert.ok(joined.includes(\"[orchestrate] BLOCKED:\"), \"blocked transition must print a BLOCKED stderr line\")\n\t\tassert.ok(joined.includes('group \"w1\"'), \"BLOCKED line must name the group\")\n\t\tassert.ok(joined.includes(\"Which auth strategy should I use?\"), \"BLOCKED line must include the question text\")\n\t\tassert.ok(\n\t\t\tjoined.includes(\"scripts/headlesscode-answer.sh .worktrees/w1\"),\n\t\t\t\"BLOCKED line must show the answer command with the worktree path\",\n\t\t)\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\nasync function testWatchGroupsDoesNotRepeatBlockedLineWhileStillBlocked(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\tconst statePath = path.join(repoRoot, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, { ...defaultState(\"round-1\"), groups: [baseGroup()] })\n\t\tawait fs.writeFile(\n\t\t\tpath.join(wtPath, \".harness.needs-decision\"),\n\t\t\tJSON.stringify({ question: \"stay blocked\", askedAt: \"2026-08-01T00:00:00.000Z\" }),\n\t\t\t\"utf-8\",\n\t\t)\n\n\t\tconst controller = new AbortController()\n\t\tconst lines: string[] = []\n\t\tconst watchPromise = watchGroups({\n\t\t\trepoRoot,\n\t\t\tstatePath,\n\t\t\tpollIntervalMs: 20,\n\t\t\tstderrWriter: (text) => lines.push(text),\n\t\t\tsignal: controller.signal,\n\t\t})\n\t\t// Let several poll iterations run while the group stays blocked, then stop.\n\t\tconst stopTimer = setTimeout(() => controller.abort(), 200)\n\t\ttry {\n\t\t\tawait watchPromise\n\t\t} finally {\n\t\t\tclearTimeout(stopTimer)\n\t\t}\n\n\t\tconst blockedLines = lines.filter((l) => l.includes(\"BLOCKED\"))\n\t\tassert.equal(blockedLines.length, 1, \"the BLOCKED line must appear exactly once while the group stays blocked\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\nasync function testWatchGroupsPrintsDoneTransitionToStderr(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\tconst statePath = path.join(repoRoot, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, { ...defaultState(\"round-1\"), groups: [baseGroup()] })\n\t\tawait fs.mkdir(path.join(wtPath, \".harness.done\"))\n\t\tawait fs.writeFile(path.join(wtPath, \".harness.exit\"), \"0\", \"utf-8\")\n\n\t\tconst lines: string[] = []\n\t\tconst summary = await watchGroups({\n\t\t\trepoRoot,\n\t\t\tstatePath,\n\t\t\tpollIntervalMs: 20,\n\t\t\tstderrWriter: (text) => lines.push(text),\n\t\t})\n\n\t\tassert.equal(summary.allTerminal, true)\n\t\tconst joined = lines.join(\"\")\n\t\tassert.ok(joined.includes(\"[orchestrate] DONE:\"), \"done transition must print a DONE stderr line\")\n\t\tassert.ok(joined.includes('group \"w1\"'), \"DONE line must name the group\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n/**\n * Mandatory cost/token history recording: a group reaching \"done\" must get\n * its combined usage recorded to the central cost-history.jsonl exactly\n * once, with `cost_recorded` set on the persisted group so it's never\n * re-recorded on a later poll. This is the end-to-end counterpart to\n * cost-history.test.ts's unit coverage of recordGroupCost itself.\n */\nasync function testWatchGroupsRecordsCostOnDoneTransition(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tconst usageDir = path.join(wtPath, \".headlesscode\", \"usage\")\n\t\tawait fs.mkdir(usageDir, { recursive: true })\n\t\tconst statePath = path.join(repoRoot, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, { ...defaultState(\"round-1\"), groups: [baseGroup({ issues: [42] })] })\n\t\tawait fs.mkdir(path.join(wtPath, \".harness.done\"))\n\t\tawait fs.writeFile(path.join(wtPath, \".harness.exit\"), \"0\", \"utf-8\")\n\t\tawait fs.writeFile(\n\t\t\tpath.join(usageDir, \"session-1.jsonl\"),\n\t\t\t`${JSON.stringify({ sessionId: \"session-1\", costUsd: 0.05, inputTokens: 1000, outputTokens: 100, cachedTokens: 400, iterations: 12 })}\\n`,\n\t\t\t\"utf-8\",\n\t\t)\n\n\t\tconst summary = await watchGroups({\n\t\t\trepoRoot,\n\t\t\tstatePath,\n\t\t\tpollIntervalMs: 20,\n\t\t\tstderrWriter: () => {},\n\t\t\treviewEnabled: false,\n\t\t})\n\t\tassert.equal(summary.allTerminal, true)\n\n\t\tconst persisted = loadStateSync(statePath)\n\t\tconst group = persisted.groups.find((g) => g.name === \"w1\")\n\t\tassert.ok(group?.cost_recorded, \"cost_recorded must be set once the group is terminal\")\n\n\t\tconst { readCostHistory } = await import(\"../cost-history.js\")\n\t\tconst records = await readCostHistory(repoRoot)\n\t\tassert.equal(records.length, 1, \"exactly one cost-history record must be written\")\n\t\tassert.deepEqual(records[0]?.issues, [42])\n\t\tassert.equal(records[0]?.costUsd, 0.05)\n\t\tassert.equal(records[0]?.status, \"done\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n/**\n * 2026-08-05 incident: recordCostIfSettled originally fired the FIRST time\n * a group was observed terminal — before review (or QA) even ran. Since\n * review/QA are separate HeadlessSession runs against the SAME worktree,\n * each writing their own `.headlesscode/usage/*.jsonl`, and nothing\n * re-triggers a usage rollup for a \"done\" group unless a rework respawn\n * happens, their real cost was silently never captured. This reproduces\n * the fix: with review enabled, a \"done\" group must NOT be recorded until\n * `review_verdict` is set, and the recorded total must include the review\n * session's own usage file, not just the original worker's.\n */\nasync function testWatchGroupsWaitsForReviewBeforeRecordingCost(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tconst usageDir = path.join(wtPath, \".headlesscode\", \"usage\")\n\t\tawait fs.mkdir(usageDir, { recursive: true })\n\t\tconst statePath = path.join(repoRoot, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, { ...defaultState(\"round-1\"), groups: [baseGroup({ issues: [42] })] })\n\t\tawait fs.mkdir(path.join(wtPath, \".harness.done\"))\n\t\tawait fs.writeFile(path.join(wtPath, \".harness.exit\"), \"0\", \"utf-8\")\n\t\tawait fs.writeFile(\n\t\t\tpath.join(usageDir, \"worker.jsonl\"),\n\t\t\t`${JSON.stringify({ sessionId: \"worker\", costUsd: 0.05, inputTokens: 1000, outputTokens: 100, cachedTokens: 400, iterations: 12 })}\\n`,\n\t\t\t\"utf-8\",\n\t\t)\n\n\t\tlet callbackCalls = 0\n\t\tconst summary = await watchGroups({\n\t\t\trepoRoot,\n\t\t\tstatePath,\n\t\t\tpollIntervalMs: 20,\n\t\t\tstderrWriter: () => {},\n\t\t\treviewEnabled: true,\n\t\t\tonGroupUpdate: async (group) => {\n\t\t\t\tcallbackCalls++\n\t\t\t\t// Simulate the real review step: it's a SEPARATE HeadlessSession\n\t\t\t\t// against the same worktree, so it writes its OWN usage file,\n\t\t\t\t// then reports a clean verdict — same shape as cli.ts's real\n\t\t\t\t// runReview + state patch.\n\t\t\t\tawait fs.writeFile(\n\t\t\t\t\tpath.join(usageDir, \"review.jsonl\"),\n\t\t\t\t\t`${JSON.stringify({ sessionId: \"review\", costUsd: 0.02, inputTokens: 500, outputTokens: 50, cachedTokens: 100, iterations: 8 })}\\n`,\n\t\t\t\t\t\"utf-8\",\n\t\t\t\t)\n\t\t\t\tsaveStateSync(\n\t\t\t\t\tstatePath,\n\t\t\t\t\tupdateGroup(loadStateSync(statePath), group.name, {\n\t\t\t\t\t\treview_verdict: \"clean\",\n\t\t\t\t\t\tpending_review_findings: [],\n\t\t\t\t\t\treviewed_at: new Date().toISOString(),\n\t\t\t\t\t}),\n\t\t\t\t)\n\t\t\t\treturn undefined\n\t\t\t},\n\t\t})\n\t\tassert.equal(summary.allTerminal, true)\n\t\tassert.equal(callbackCalls, 1, \"review must run exactly once\")\n\n\t\tconst persisted = loadStateSync(statePath)\n\t\tconst group = persisted.groups.find((g) => g.name === \"w1\")\n\t\tassert.ok(group?.cost_recorded, \"cost must be recorded once review is settled\")\n\t\tassert.equal(group?.review_verdict, \"clean\")\n\n\t\tconst { readCostHistory } = await import(\"../cost-history.js\")\n\t\tconst records = await readCostHistory(repoRoot)\n\t\tassert.equal(records.length, 1, \"exactly one cost-history record, recorded after review\")\n\t\tassert.equal(\n\t\t\trecords[0]?.costUsd,\n\t\t\t0.07,\n\t\t\t\"recorded cost must include BOTH the worker's and the review session's usage, not just the worker's\",\n\t\t)\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n/**\n * Issue #24 (2026-08-05): watchGroups used to await each group's\n * onGroupUpdate INLINE in the per-group for-loop, so one group's long\n * review/QA fully monopolized the watcher — no other group's completion was\n * even detected until the in-flight one resolved. Live impact: a settled\n * group sat fully idle for 30+ minutes behind another group's review+QA in\n * the same round. This reproduces the fix: group \"w1\"'s callback blocks on\n * a gate that only opens once group \"w2\" has ALREADY completed its own\n * callback, proving w2's review runs and finishes while w1's is still stuck\n * — i.e. groups are no longer serialized through the watcher.\n */\nasync function testWatchGroupsRunsReviewForMultipleGroupsConcurrently(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst w1Path = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tconst w2Path = path.join(repoRoot, \".worktrees\", \"w2\")\n\t\tawait fs.mkdir(w1Path, { recursive: true })\n\t\tawait fs.mkdir(w2Path, { recursive: true })\n\t\tconst statePath = path.join(repoRoot, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, {\n\t\t\t...defaultState(\"round-1\"),\n\t\t\tgroups: [baseGroup({ name: \"w1\", worktree: \".worktrees/w1\" }), baseGroup({ name: \"w2\", worktree: \".worktrees/w2\" })],\n\t\t})\n\t\tawait fs.mkdir(path.join(w1Path, \".harness.done\"))\n\t\tawait fs.writeFile(path.join(w1Path, \".harness.exit\"), \"0\", \"utf-8\")\n\t\tawait fs.mkdir(path.join(w2Path, \".harness.done\"))\n\t\tawait fs.writeFile(path.join(w2Path, \".harness.exit\"), \"0\", \"utf-8\")\n\n\t\tlet w2Finished = false\n\t\tlet resolveW1Started: (() => void) | undefined\n\t\tconst w1Started = new Promise<void>((resolve) => {\n\t\t\tresolveW1Started = resolve\n\t\t})\n\n\t\tconst summary = await watchGroups({\n\t\t\trepoRoot,\n\t\t\tstatePath,\n\t\t\tpollIntervalMs: 20,\n\t\t\tstderrWriter: () => {},\n\t\t\treviewEnabled: true,\n\t\t\tonGroupUpdate: async (group) => {\n\t\t\t\tif (group.name === \"w1\") {\n\t\t\t\t\tresolveW1Started?.()\n\t\t\t\t\t// Block until w2's callback has fully finished — if the\n\t\t\t\t\t// watcher still serialized groups, this would deadlock\n\t\t\t\t\t// (w2's callback would never even start), so the test\n\t\t\t\t\t// itself is the proof: it only completes if w2 ran\n\t\t\t\t\t// concurrently with w1 still stuck here.\n\t\t\t\t\tconst deadline = Date.now() + 5000\n\t\t\t\t\twhile (!w2Finished && Date.now() < deadline) {\n\t\t\t\t\t\tawait new Promise((r) => setTimeout(r, 5))\n\t\t\t\t\t}\n\t\t\t\t\tassert.equal(w2Finished, true, \"w2 must finish while w1's callback is still blocked\")\n\t\t\t\t\tsaveStateSync(\n\t\t\t\t\t\tstatePath,\n\t\t\t\t\t\tupdateGroup(loadStateSync(statePath), \"w1\", {\n\t\t\t\t\t\t\treview_verdict: \"clean\",\n\t\t\t\t\t\t\tpending_review_findings: [],\n\t\t\t\t\t\t\treviewed_at: new Date().toISOString(),\n\t\t\t\t\t\t}),\n\t\t\t\t\t)\n\t\t\t\t\treturn undefined\n\t\t\t\t}\n\t\t\t\tawait w1Started\n\t\t\t\tsaveStateSync(\n\t\t\t\t\tstatePath,\n\t\t\t\t\tupdateGroup(loadStateSync(statePath), \"w2\", {\n\t\t\t\t\t\treview_verdict: \"clean\",\n\t\t\t\t\t\tpending_review_findings: [],\n\t\t\t\t\t\treviewed_at: new Date().toISOString(),\n\t\t\t\t\t}),\n\t\t\t\t)\n\t\t\t\tw2Finished = true\n\t\t\t\treturn undefined\n\t\t\t},\n\t\t})\n\n\t\tassert.equal(summary.allTerminal, true)\n\t\tconst persisted = loadStateSync(statePath)\n\t\tassert.equal(persisted.groups.find((g) => g.name === \"w1\")?.review_verdict, \"clean\")\n\t\tassert.equal(persisted.groups.find((g) => g.name === \"w2\")?.review_verdict, \"clean\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n/**\n * Issue #116: the watcher writes a heartbeat file (<statePath>.watcher) at\n * poll cadence so a concurrent read-side `status --wait` can tell a live\n * watch loop owns the state and must NOT persist its own read-side\n * reconciliation. The heartbeat must exist before the first poll pass.\n */\nasync function testWatchGroupsWritesWatcherHeartbeat(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\tconst statePath = path.join(repoRoot, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, { ...defaultState(\"round-1\"), groups: [baseGroup()] })\n\t\tawait fs.mkdir(path.join(wtPath, \".harness.done\"))\n\t\tawait fs.writeFile(path.join(wtPath, \".harness.exit\"), \"0\", \"utf-8\")\n\n\t\tconst heartbeatPath = `${statePath}.watcher`\n\t\tconst controller = new AbortController()\n\t\tawait watchGroups({\n\t\t\trepoRoot,\n\t\t\tstatePath,\n\t\t\tpollIntervalMs: 20,\n\t\t\tstderrWriter: () => {},\n\t\t\treviewEnabled: false,\n\t\t\t// Stop the loop once the heartbeat has been observed and the group\n\t\t\t// has reached done (otherwise it loops forever).\n\t\t\tonGroupUpdate: async () => {\n\t\t\t\tcontroller.abort()\n\t\t\t},\n\t\t\tsignal: controller.signal,\n\t\t})\n\n\t\tconst stat = await fs.stat(heartbeatPath)\n\t\tassert.ok(stat.isFile(), \"heartbeat file exists\")\n\t\tassert.ok(Date.now() - stat.mtimeMs < 60_000, \"heartbeat was written recently (this run)\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\nasync function testWatchGroupsPrintsFailedTransitionToStderr(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\tconst statePath = path.join(repoRoot, \".worktrees\", \".orchestrator-state.json\")\n\t\tsaveStateSync(statePath, { ...defaultState(\"round-1\"), groups: [baseGroup()] })\n\t\tawait fs.mkdir(path.join(wtPath, \".harness.done\"))\n\t\tawait fs.writeFile(path.join(wtPath, \".harness.exit\"), \"1\", \"utf-8\")\n\n\t\tconst lines: string[] = []\n\t\tconst summary = await watchGroups({\n\t\t\trepoRoot,\n\t\t\tstatePath,\n\t\t\tpollIntervalMs: 20,\n\t\t\tstderrWriter: (text) => lines.push(text),\n\t\t})\n\n\t\tassert.equal(summary.allTerminal, true)\n\t\tconst joined = lines.join(\"\")\n\t\tassert.ok(joined.includes(\"[orchestrate] FAILED:\"), \"failed transition must print a FAILED stderr line\")\n\t\tassert.ok(joined.includes('group \"w1\"'), \"FAILED line must name the group\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n/**\n * 2026-08-02 incident regression: a group past the stall timeout whose\n * worker process has ACTUALLY died (not just a missing pid file — a real\n * dead pid recorded in a stale `.harness.pid`) must resolve to \"failed\"\n * immediately, not sit reporting \"still stalled\" forever. Before the fix,\n * `hasPid` only checked file existence, so a stale pid file made a dead\n * worker indistinguishable from a live one — the group could never resolve.\n */\nasync function testStallGuardResolvesToFailedWhenPidIsDead(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\t// A pid that is guaranteed dead by the time we read it: spawn a\n\t\t// trivial child, let it exit, and use its (now-released) pid.\n\t\tconst dead = spawnSync(process.execPath, [\"-e\", \"process.exit(0)\"])\n\t\tconst deadPid = dead.pid\n\t\tassert.ok(deadPid, \"expected the trivial child to report a pid\")\n\t\tawait fs.writeFile(path.join(wtPath, \".harness.pid\"), String(deadPid), \"utf-8\")\n\n\t\tconst longAgo = new Date(Date.now() - DEFAULT_STALL_TIMEOUT_MS * 10).toISOString()\n\t\tconst group = baseGroup({ spawned: longAgo })\n\t\tconst patch = inspectGroup(repoRoot, group, Date.now(), DEFAULT_STALL_TIMEOUT_MS)\n\n\t\tassert.ok(patch, \"a dead-pid stalled group must resolve, not silently do nothing\")\n\t\tassert.equal(patch?.status, \"failed\", \"a confirmed-dead worker must resolve to failed, not sit stalled forever\")\n\t\tassert.equal(patch?.stalled, true)\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n/**\n * 2026-08-02 incident regression, the actual busy-loop cause: a group past\n * the stall timeout whose worker IS still genuinely alive must report the\n * stall ONCE (the transition into `stalled: true`), then return `undefined`\n * on every subsequent poll as long as nothing has changed — not a fresh\n * patch every single time. Before the fix, this branch returned a new\n * patch object unconditionally on every call, which `watchGroups`' \"only\n * sleep if nothing changed\" loop treated as \"something changed\" forever,\n * producing a zero-delay busy loop (observed: 11+ hours at ~76% CPU on a\n * real orchestrator round).\n */\nasync function testStallGuardReportsOnceThenStopsWhileStillAlive(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\t// This test process's own pid is guaranteed alive for the duration.\n\t\tawait fs.writeFile(path.join(wtPath, \".harness.pid\"), String(process.pid), \"utf-8\")\n\n\t\tconst longAgo = new Date(Date.now() - DEFAULT_STALL_TIMEOUT_MS * 10).toISOString()\n\t\tconst now = Date.now()\n\n\t\t// First poll: not yet marked stalled -> must report it (once).\n\t\tconst freshGroup = baseGroup({ spawned: longAgo })\n\t\tconst firstPatch = inspectGroup(repoRoot, freshGroup, now, DEFAULT_STALL_TIMEOUT_MS)\n\t\tassert.ok(firstPatch, \"the first stall detection must produce a patch\")\n\t\tassert.equal(firstPatch?.status, undefined, \"still alive -> status must NOT flip to failed\")\n\t\tassert.equal(firstPatch?.stalled, true)\n\n\t\t// Second poll: simulate the patch having been persisted (stalled:\n\t\t// true already recorded) and nothing else changed -- this is the\n\t\t// exact repeated-call shape that caused the busy loop.\n\t\tconst alreadyStalledGroup = baseGroup({ spawned: longAgo, stalled: true })\n\t\tconst secondPatch = inspectGroup(repoRoot, alreadyStalledGroup, now + 1000, DEFAULT_STALL_TIMEOUT_MS)\n\t\tassert.equal(secondPatch, undefined, \"an unresolved stall that hasn't changed must not produce a fresh patch every poll\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n// ─── isIterationExhaustion: the continuable-failure predicate ────────────────\n// Only the harness's exact \"Max iterations (N) reached without task\n// completion\" error marks a failure as iteration-exhaustion (the auto-continue\n// signal); budget stops and real errors must never match.\n\nasync function testIsIterationExhaustionMatchesExactError(): Promise<void> {\n\tassert.equal(\n\t\tisIterationExhaustion(\"headlesscode: task failed: Max iterations (50) reached without task completion\"),\n\t\ttrue,\n\t\t\"the harness CLI's stderr line (redirected into harness.log) must match\",\n\t)\n\tassert.equal(\n\t\tisIterationExhaustion(\"... some log ... Max iterations (3) reached without task completion\"),\n\t\ttrue,\n\t\t\"the exact error substring anywhere in the summary matches\",\n\t)\n}\n\nasync function testIsIterationExhaustionRejectsOtherFailures(): Promise<void> {\n\tassert.equal(\n\t\tisIterationExhaustion(\"headlesscode: task aborted by budget: max cost exceeded\"),\n\t\tfalse,\n\t\t\"a budget stop is NOT iteration exhaustion (must never auto-continue)\",\n\t)\n\tassert.equal(\n\t\tisIterationExhaustion(\"headlesscode: task failed: consecutive mistakes\"),\n\t\tfalse,\n\t\t\"a real error is NOT iteration exhaustion\",\n\t)\n\tassert.equal(isIterationExhaustion(undefined), false, \"no summary is never exhaustion\")\n\tassert.equal(isIterationExhaustion(\"\"), false, \"empty summary is never exhaustion\")\n}\n\n// ─── isProviderFailure: the second continuable-failure predicate ────────────\n// A transient LLM-provider failure on the MAIN call (src/engine/loop.ts's\n// callMainLlm) — observed live 2026-08-08: a hard-pinned model with no\n// fallback provider hit an HTTP 520 mid-session and killed the whole thing.\n// This earns the same auto-continue treatment as the iteration cap; a real\n// task/code failure must never match.\n\nasync function testIsProviderFailureMatchesKnownShapes(): Promise<void> {\n\tassert.equal(\n\t\tisProviderFailure(\n\t\t\t'headlesscode: task failed: LLM request failed on iteration 28: OpenRouter returned HTTP 520: {\"error\":{\"message\":\"Provider returned error\",\"code\":520,\"metadata\":{\"raw\":\"error code: 520\\\\n\",\"provider_name\":\"DeepSeek\",\"is_byok\":false}}}',\n\t\t),\n\t\ttrue,\n\t\t\"a provider 5xx on the main call must match\",\n\t)\n\tassert.equal(\n\t\tisProviderFailure(\n\t\t\t'LLM request failed on iteration 12: OpenRouter returned HTTP 429: {\"error\":{\"message\":\"Rate limited\"}}',\n\t\t),\n\t\ttrue,\n\t\t\"a provider 429 must match\",\n\t)\n\tassert.equal(\n\t\tisProviderFailure(\n\t\t\t'LLM request failed on iteration 5: OpenRouter returned HTTP 404: {\"error\":{\"message\":\"No allowed providers are available for the selected model.\"}}',\n\t\t),\n\t\ttrue,\n\t\t'the \"no allowed providers\" 404 must match despite the 4xx status (see isRetryableOpenRouterError)',\n\t)\n\tassert.equal(\n\t\tisProviderFailure(\"LLM request failed on iteration 3: Network error calling OpenRouter: fetch failed\"),\n\t\ttrue,\n\t\t\"a raw network-transport failure must match\",\n\t)\n}\n\nasync function testIsProviderFailureRejectsOtherFailures(): Promise<void> {\n\tassert.equal(\n\t\tisProviderFailure(\n\t\t\t'LLM request failed on iteration 9: OpenRouter returned HTTP 401: {\"error\":{\"message\":\"Invalid API key\"}}',\n\t\t),\n\t\tfalse,\n\t\t\"a deterministic 4xx (auth failure) must NOT auto-continue — retrying changes nothing\",\n\t)\n\tassert.equal(\n\t\tisProviderFailure(\"headlesscode: task aborted by budget: max cost exceeded\"),\n\t\tfalse,\n\t\t\"a budget stop is not a provider failure\",\n\t)\n\tassert.equal(\n\t\tisProviderFailure(\"headlesscode: task failed: Max iterations (50) reached without task completion\"),\n\t\tfalse,\n\t\t\"iteration exhaustion is handled by isIterationExhaustion, not this predicate\",\n\t)\n\tassert.equal(isProviderFailure(undefined), false, \"no summary is never a provider failure\")\n\tassert.equal(isProviderFailure(\"\"), false, \"empty summary is never a provider failure\")\n}\n\n// ─── computeTotalUsage / computeBatchUsage (issue #118) ─────────────────────\n\n/** A group usage fixture (cost, tokens, iterations). */\nfunction usageFixture(costUsd: number, iterations: number): OrchestratorGroup[\"usage\"] {\n\treturn { costUsd, inputTokens: 1000, outputTokens: 500, iterations }\n}\n\n/** State with two batches' worth of groups: current batch + one historical round. */\nfunction twoBatchState(): OrchestratorState {\n\tlet state = defaultState(\"round-2026-08-17\")\n\t// Current batch groups (spawned timestamps carry the batch date prefix).\n\tstate = updateGroup(\n\t\tstate,\n\t\t\"w1\",\n\t\tbaseGroup({ name: \"w1\", status: \"done\", spawned: \"2026-08-17T08:00:00.000Z\", usage: usageFixture(0.5, 50) }),\n\t)\n\tstate = updateGroup(\n\t\tstate,\n\t\t\"w2\",\n\t\tbaseGroup({ name: \"w2\", status: \"done\", spawned: \"2026-08-17T09:00:00.000Z\", usage: usageFixture(0.3, 30) }),\n\t)\n\t// A historical group from a PRIOR round, retained in the state file for\n\t// history/cleanup bookkeeping (this is the accumulation that makes\n\t// totalUsage misleading for \"what did THIS round cost?\").\n\tstate = updateGroup(\n\t\tstate,\n\t\t\"w-old\",\n\t\tbaseGroup({ name: \"w-old\", status: \"done\", spawned: \"2026-08-10T10:00:00.000Z\", usage: usageFixture(9.0, 900) }),\n\t)\n\treturn state\n}\n\nasync function testComputeBatchUsageScopesToCurrentBatch(): Promise<void> {\n\tconst state = twoBatchState()\n\tconst batch = computeBatchUsage(state)\n\tassert.ok(batch, \"current-batch groups have usage -> a batchUsage is produced\")\n\tassert.equal(batch?.costUsd, 0.8, \"sums ONLY the current batch's groups (w1 + w2), not w-old\")\n\tassert.equal(batch?.iterations, 80)\n\tassert.equal(batch?.inputTokens, 2000)\n\tassert.equal(batch?.outputTokens, 1000)\n}\n\nasync function testComputeBatchUsageExcludesHistoricalGroups(): Promise<void> {\n\tconst state = twoBatchState()\n\tconst total = computeTotalUsage(state)\n\tassert.ok(total, \"totalUsage exists\")\n\tassert.equal(total?.costUsd, 9.8, \"totalUsage stays cumulative across ALL groups (w1 + w2 + w-old)\")\n\tconst batch = computeBatchUsage(state)\n\tassert.equal(batch?.costUsd, 0.8, \"batchUsage excludes the historical round's group\")\n}\n\nasync function testComputeBatchUsageUndefinedWithoutBatchOrGroupUsage(): Promise<void> {\n\t// No batch id at all -> nothing to scope against.\n\tassert.equal(computeBatchUsage(defaultState(\"unnamed\")), undefined)\n\t// Current-batch groups with no usage records -> undefined (never a spurious all-zero rollup).\n\tconst empty = twoBatchState()\n\tfor (const g of empty.groups) {\n\t\tempty.groups = empty.groups.map((gg) => ({ ...gg, usage: undefined }))\n\t}\n\tassert.equal(computeBatchUsage(empty), undefined)\n}\n\nasync function testComputeBatchUsageMatchesSpawnedByDatePrefix(): Promise<void> {\n\t// A timestamp-prefixed batch (e.g. custom --batch) matches by prefix, and\n\t// the 'T' guard (>= 11 chars) keeps a truncated prefix from over-matching.\n\tlet state = defaultState(\"round-2026-08-17T12\")\n\tstate = updateGroup(\n\t\tstate,\n\t\t\"w1\",\n\t\tbaseGroup({ name: \"w1\", status: \"done\", spawned: \"2026-08-17T12:00:00.000Z\", usage: usageFixture(0.4, 40) }),\n\t)\n\tstate = updateGroup(\n\t\tstate,\n\t\t\"w2\",\n\t\tbaseGroup({ name: \"w2\", status: \"done\", spawned: \"2026-08-17T13:00:00.000Z\", usage: usageFixture(0.2, 20) }),\n\t)\n\tstate = updateGroup(\n\t\tstate,\n\t\t\"w-old\",\n\t\tbaseGroup({ name: \"w-old\", status: \"done\", spawned: \"2026-08-16T12:00:00.000Z\", usage: usageFixture(5.0, 500) }),\n\t)\n\tconst batch = computeBatchUsage(state)\n\tassert.ok(batch, \"timestamp-prefixed batch matches by prefix\")\n\tassert.equal(batch?.costUsd, 0.4, \"only groups spawned under the batch's exact date/hour prefix count (w2 is hour 13)\")\n\tassert.equal(batch?.iterations, 40)\n}\n\n/**\n\t* 2026-08-05 incident regression: `inspectGroup`'s captured `summary` field\n * silently dropped the ACTUAL final lines of a long-running worker's\n * harness.log. tailLog() correctly returns the last SUMMARY_TAIL_LINES\n * lines of the current run, but that tail was then capped with\n * `.slice(0, 4000)` — the FIRST 4000 chars of an already-end-anchored tail\n * — which discards the tail's own most recent content when the 40-line\n * window exceeds 4000 chars (easy: harness.log's JSON usage lines commonly\n * run 200-300+ chars each). In a real dispatch round this made\n * `isIterationExhaustion(group.summary)` return false for a worker that\n * GENUINELY hit --max-iterations, because the \"Max iterations (N) reached\"\n * line — always the true last line — never survived into `summary`. Two\n * real, separate consequences from the one bug: auto-continuation never\n * fired, and status output shown to a human/agent never reflected the\n * worker's real final outcome.\n */\nasync function testInspectGroupSummaryPreservesTrueTailNotHead(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst wtPath = path.join(repoRoot, \".worktrees\", \"w1\")\n\t\tawait fs.mkdir(wtPath, { recursive: true })\n\t\t// Pad with enough long lines that the 40-line tail window exceeds 4000\n\t\t// chars well before reaching the final line — reproduces the real\n\t\t// harness.log shape (verbose JSON usage-total lines every iteration).\n\t\tconst padLine =\n\t\t\t'[2026-08-05T14:00:00.000Z] INFO  [usage] running total {\"iteration\":1,\"costUsd\":0.01,\"inputTokens\":100000,\"outputTokens\":1000,\"cachedTokens\":90000,\"lastPromptTokens\":10000,\"lastCachedTokens\":9000}'\n\t\tconst padding = Array.from({ length: 39 }, () => padLine).join(\"\\n\")\n\t\tconst finalLine = \"headlesscode: task failed: Max iterations (50) reached without task completion\"\n\t\tawait fs.writeFile(path.join(wtPath, \"harness.log\"), `${padding}\\n${finalLine}\\n`, \"utf-8\")\n\t\tawait fs.mkdir(path.join(wtPath, \".harness.done\"))\n\t\tawait fs.writeFile(path.join(wtPath, \".harness.exit\"), \"1\", \"utf-8\")\n\n\t\tconst patch = inspectGroup(repoRoot, baseGroup(), Date.now(), DEFAULT_STALL_TIMEOUT_MS)\n\t\tassert.ok(patch, \"a done marker with a failing exit code must produce a patch\")\n\t\tassert.equal(patch?.status, \"failed\")\n\t\tassert.ok(\n\t\t\tpatch?.summary?.includes(\"Max iterations (50) reached\"),\n\t\t\t`captured summary must include the real final error line, got tail: ${patch?.summary?.slice(-200)}`,\n\t\t)\n\t\tassert.equal(\n\t\t\tisIterationExhaustion(patch?.summary),\n\t\t\ttrue,\n\t\t\t\"the captured summary must actually be detected as iteration exhaustion (this is what gates auto-continuation)\",\n\t\t)\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n// ─── tailLog: run-separator scoping (restart must not lose prior log/stats) ──\n// scripts/run-worker.sh now appends to harness.log across continuation/rework\n// respawns on the same worktree (never truncates it), writing a run-start\n// separator before each session. tailLog() must scope its summary to content\n// after the LAST separator so a short current-run log never inherits a stale\n// \"Max iterations reached\" line from an earlier session in the same file.\n\nasync function testTailLogScopesToLatestRunAfterAppend(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst logPath = path.join(repoRoot, \"harness.log\")\n\t\tawait fs.writeFile(\n\t\t\tlogPath,\n\t\t\t[\n\t\t\t\t\"===== headlesscode run start: 2026-08-01T00:00:00Z =====\",\n\t\t\t\t\"first session doing work\",\n\t\t\t\t\"headlesscode: task failed: Max iterations (50) reached without task completion\",\n\t\t\t\t\"===== headlesscode run start: 2026-08-01T01:00:00Z =====\",\n\t\t\t\t\"second session picked up where the first left off\",\n\t\t\t\t\"headlesscode: task completed successfully\",\n\t\t\t].join(\"\\n\"),\n\t\t\t\"utf-8\",\n\t\t)\n\n\t\tconst summary = tailLog(logPath)\n\t\tassert.ok(!summary.includes(\"Max iterations\"), \"must not see the previous session's exhaustion line\")\n\t\tassert.ok(summary.includes(\"second session picked up\"), \"must see the current session's own output\")\n\t\tassert.equal(isIterationExhaustion(summary), false, \"a short current run must not misfire as exhaustion\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\nasync function testTailLogPreservesFullHistoryOnDisk(): Promise<void> {\n\tconst repoRoot = await tmpRepo()\n\ttry {\n\t\tconst logPath = path.join(repoRoot, \"harness.log\")\n\t\tawait fs.writeFile(logPath, \"first session output\\n\", \"utf-8\")\n\t\tawait fs.appendFile(\n\t\t\tlogPath,\n\t\t\t\"\\n===== headlesscode run start: 2026-08-01T01:00:00Z =====\\nsecond session output\\n\",\n\t\t\t\"utf-8\",\n\t\t)\n\n\t\tconst raw = await fs.readFile(logPath, \"utf-8\")\n\t\tassert.ok(raw.includes(\"first session output\"), \"appending must never destroy a prior session's log\")\n\t\tassert.ok(raw.includes(\"second session output\"), \"and must include the new session's log too\")\n\t} finally {\n\t\tawait fs.rm(repoRoot, { recursive: true, force: true })\n\t}\n}\n\n// ─── Runner ──────────────────────────────────────────────────────────────────\n\nconst tests: Array<[string, () => Promise<void>]> = [\n\t[\"inspectGroup: needs-decision marker -> status blocked with question recorded\", testInspectGroupDetectsNeedsDecisionMarker],\n\t[\"inspectGroup: already blocked on the same question -> no patch (no churn)\", testInspectGroupNoChangeWhenAlreadyBlockedOnSameQuestion],\n\t[\"inspectGroup: marker removed while blocked -> status running, blocked cleared\", testInspectGroupFlowsBackToRunningWhenMarkerRemoved],\n\t[\"inspectGroup: blocked group is exempt from the stall guard\", testBlockedGroupIsExemptFromStallGuard],\n\t[\"inspectGroup: stalled + confirmed-dead pid resolves to failed\", testStallGuardResolvesToFailedWhenPidIsDead],\n\t[\"inspectGroup: stalled + still-alive pid reports once, then stops (busy-loop regression)\", testStallGuardReportsOnceThenStopsWhileStillAlive],\n\t[\"watchGroups: blocked -> running -> done end-to-end transition\", testWatchGroupsBlockedThenUnblockedFlow],\n\t[\"watchGroups: BLOCKED line printed once on the transition into blocked\", testWatchGroupsPrintsBlockedTransitionToStderr],\n\t[\"watchGroups: BLOCKED line not repeated while the group stays blocked\", testWatchGroupsDoesNotRepeatBlockedLineWhileStillBlocked],\n\t[\"watchGroups: DONE line printed on the transition to done\", testWatchGroupsPrintsDoneTransitionToStderr],\n\t[\"watchGroups: records cost history exactly once on the done transition\", testWatchGroupsRecordsCostOnDoneTransition],\n\t[\"watchGroups: waits for review before recording cost, then includes the review session's own usage\", testWatchGroupsWaitsForReviewBeforeRecordingCost],\n\t[\"watchGroups: runs review for multiple groups concurrently, not serialized (issue #24)\", testWatchGroupsRunsReviewForMultipleGroupsConcurrently],\n\t[\"watchGroups: FAILED line printed on the transition to failed\", testWatchGroupsPrintsFailedTransitionToStderr],\n\t[\"watchGroups: writes the watcher heartbeat file at poll cadence (issue #116)\", testWatchGroupsWritesWatcherHeartbeat],\n\t[\"isIterationExhaustion matches the exact max-iterations error\", testIsIterationExhaustionMatchesExactError],\n\t[\"isIterationExhaustion rejects budget/real failures and empty summaries\", testIsIterationExhaustionRejectsOtherFailures],\n\t[\"isProviderFailure matches provider 5xx/429/no-allowed-providers/network-error shapes\", testIsProviderFailureMatchesKnownShapes],\n\t[\"isProviderFailure rejects deterministic 4xx, budget stops, and iteration exhaustion\", testIsProviderFailureRejectsOtherFailures],\n\t[\"computeBatchUsage scopes usage to the current batch, excluding historical groups\", testComputeBatchUsageScopesToCurrentBatch],\n\t[\"computeTotalUsage stays cumulative while computeBatchUsage excludes history\", testComputeBatchUsageExcludesHistoricalGroups],\n\t[\"computeBatchUsage is undefined without a batch id or any group usage\", testComputeBatchUsageUndefinedWithoutBatchOrGroupUsage],\n\t[\"computeBatchUsage matches a timestamp-prefixed batch by prefix\", testComputeBatchUsageMatchesSpawnedByDatePrefix],\n\t[\"inspectGroup: captured summary preserves the true tail, not the head, of a long harness.log\", testInspectGroupSummaryPreservesTrueTailNotHead],\n\t[\"tailLog: scopes the summary to content after the latest run-start separator\", testTailLogScopesToLatestRunAfterAppend],\n\t[\"tailLog: appended harness.log preserves every prior session's output on disk\", testTailLogPreservesFullHistoryOnDisk],\n]\n\nasync function main(): Promise<void> {\n\t// watchGroups now records cost history (cost-history.ts) as a mandatory\n\t// side effect of a group reaching a terminal status, which touches the\n\t// central project store — redirect it to a temp dir so no test run ever\n\t// writes into the real ~/.local/share/headlesscode (same defensive\n\t// pattern as config/__tests__/mode-models.test.ts).\n\tconst storeTmp = await fs.mkdtemp(path.join(os.tmpdir(), \"headlesscode-watch-store-\"))\n\tprocess.env.HEADLESSCODE_DATA_DIR = storeTmp\n\tlet failed = 0\n\ttry {\n\t\tfor (const [name, fn] of tests) {\n\t\t\ttry {\n\t\t\t\tawait fn()\n\t\t\t\tconsole.log(`  ok   ${name}`)\n\t\t\t} catch (err) {\n\t\t\t\tfailed++\n\t\t\t\tconsole.error(`  FAIL ${name}`)\n\t\t\t\tconsole.error(err instanceof Error ? err.stack ?? err.message : String(err))\n\t\t\t}\n\t\t}\n\t} finally {\n\t\tdelete process.env.HEADLESSCODE_DATA_DIR\n\t\tawait fs.rm(storeTmp, { recursive: true, force: true })\n\t}\n\tif (failed > 0) {\n\t\tconsole.error(`\\n${failed} test(s) failed`)\n\t\tprocess.exit(1)\n\t}\n\tconsole.log(`\\nAll ${tests.length} watch (blocked-status) tests passed`)\n}\n\nmain().catch((err) => {\n\tconsole.error(\"Test runner crashed:\", err)\n\tprocess.exit(1)\n})"}]
